    if(host){host.shadowRoot.getElementById(initialTab==='settings'?'settings-tab':'tasks-tab').click();return;}
    api.prepare();opener=document.activeElement;
    host=document.createElement('div');host.id='mcms-extension-workspace';const root=host.attachShadow({mode:'open'});
    const link=document.createElement('link');link.rel='stylesheet';link.href=api.styleUrl;root.append(link);
    const dialog=document.createElement('dialog');dialog.setAttribute('aria-label','Toolkit task centre and settings');
    dialog.innerHTML='<header><div><small>MAP COMMAND TOOLKIT</small><h1>Tasks & settings</h1></div><button id="close" aria-label="Close">×</button></header><nav><button id="tasks-tab" aria-pressed="true">Task centre</button><button id="settings-tab" aria-pressed="false">Settings manager</button></nav><p id="notice" role="status"></p><section id="tasks"><p>Active tasks and the latest 20 previous runs for this game account.</p><button id="stop">Stop tasks in this tab</button><div id="task-list" aria-live="polite"></div></section><section id="settings" hidden><label>Search tools, settings and help<input id="search" type="search" placeholder="Try patient sweep, recruitment, theme or safeguards…"></label><div id="search-results"></div><h2>Back up or restore preferences</h2><p>Export your preferences, or review selected groups before importing or resetting. Unselected groups stay unchanged.</p><div class="actions"><button id="backup">Export settings</button><label class="file">Import settings<input id="import" type="file" accept=".json,application/json"></label><button id="reset">Reset selected groups…</button></div><div id="preview" hidden><h2 id="preview-title"></h2><p id="preview-info"></p><button id="select-all">Select all</button><button id="select-none">Select none</button><div id="groups"></div><button id="apply">Apply selected groups</button><button id="discard">Cancel</button></div></section>';
    root.append(dialog);document.documentElement.append(host);
    const $=id=>root.getElementById(id),notice=text=>{$('notice').textContent=text;};
    $('close').onclick=close;dialog.addEventListener('keydown',event=>event.stopPropagation());dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
    if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');
    let busy=false,refreshing=false,lastTaskText='',preview=null;
    const show=tab=>{for(const name of ['tasks','settings']){$(name).hidden=name!==tab;$(name+'-tab').setAttribute('aria-pressed',String(name===tab));}};
    $('tasks-tab').onclick=()=>{show('tasks');void refresh(true);};$('settings-tab').onclick=()=>{show('settings');$('search').focus();};
    const button=(text,run)=>{const b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=run;return b;};
    const openedHost=host;
    const refresh=async(force=false)=>{
      if(refreshing||!host||(!force&&(document.hidden||$('tasks').hidden)))return;refreshing=true;
      try{
        const data=await api.tasks();if(host!==openedHost)return;
        $('stop').disabled=!data.jobs.some(j=>j.tabId===data.tabId&&j.state==='running');
        const all=[...data.jobs,...data.history].sort((a,b)=>b.updated-a.updated);
        const text=JSON.stringify(all);if(text===lastTaskText)return;lastTaskText=text;$('task-list').replaceChildren();
        if(!all.length){$('task-list').textContent='No tasks yet. Open Operations in the toolkit to choose a tool and scan.';return;}
        for(const job of all){
          const row=document.createElement('article'),title=document.createElement('h3'),status=document.createElement('p');
          title.textContent=taskNames[job.operation]||taskNames[job.type]||'Toolkit task';
          status.textContent=`${({running:'Running',complete:'Finished',cancelled:'Stopped',partial:'Partly completed',error:'Failed',interrupted:'Interrupted','check-required':'Needs checking'})[job.state]||job.state} · ${job.tabId===data.tabId?'this tab':'tab '+job.tabId} · ${new Date(job.updated).toLocaleString()}`;
          row.append(title,status);
          if(job.total){const progress=document.createElement('progress');progress.max=job.total;progress.value=job.checked||0;progress.setAttribute('aria-label',title.textContent+' progress');row.append(progress);}
          const counts=document.createElement('p');counts.textContent=[job.total?`${job.checked||0}/${job.total} checked`:null,job.type.endsWith('scan')&&Number.isFinite(job.found)?`${job.found} found`:null,Number.isFinite(job.succeeded)?`${job.succeeded} succeeded`:null,Number.isFinite(job.failed)?`${job.failed} failed`:null,Number.isFinite(job.skipped)?`${job.skipped} skipped`:null].filter(Boolean).join(' · ');row.append(counts);
          if(['interrupted','check-required','error','cancelled','partial'].includes(job.state)){const help=document.createElement('p');help.className='hint';help.textContent='Review the game’s current state, then run a fresh scan. Completed game actions are not replayed.';row.append(help);}
          if(job.tabId!==data.tabId&&job.state==='running')row.append(button('Open task tab',async()=>{try{await api.focus(job);}catch(error){notice(error.message);}}));
          $('task-list').append(row);
        }
      }catch(error){notice(error.message);}finally{refreshing=false;}
    };
    $('stop').onclick=()=>{api.cancel();notice('Stop requested. Any request already sent to the game may finish.');};
    const records=api.searchRecords();
    $('search').oninput=()=>{
      const query=$('search').value.trim().toLowerCase();$('search-results').replaceChildren();if(!query)return;
      const matches=records.filter(r=>query.split(/\s+/).every(word=>(r.label+' '+r.description).toLowerCase().includes(word))).sort((a,b)=>Number(Boolean(b.tool))-Number(Boolean(a.tool))).slice(0,30);
      if(!matches.length){$('search-results').textContent='No matching tools, settings or help. Try a feature name such as recruitment, map or audio.';return;}
      for(const record of matches){const row=document.createElement('article');row.append(button(record.label,()=>{close();api.reveal(record);}));const text=document.createElement('p');text.textContent=record.description;row.append(text);$('search-results').append(row);}
    };
    const download=value=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='MissionChief-Toolkit-settings-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
    $('backup').onclick=()=>{try{download(api.backup());notice('Settings backup downloaded.');}catch(error){notice(error.message);}};
    function renderPreview(values,title,info){
      preview={values,before:structuredClone(api.current())};$('groups').replaceChildren();$('preview-title').textContent=title;$('preview-info').textContent=info;$('preview').hidden=false;
      for(const key of Object.keys(values)){
        const row=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=key;check.checked=false;
        row.className='group';row.append(check,document.createTextNode(label(key)+(JSON.stringify(values[key])===JSON.stringify(preview.before[key])?' · unchanged':' · will change')));$('groups').append(row);
      }
      $('apply').disabled=true;
    }
    const updateSelection=()=>{$('apply').disabled=busy||!$('groups').querySelector('input:checked');};
    $('groups').onchange=updateSelection;
    for(const [id,checked]of [['select-all',true],['select-none',false]])$(id).onclick=()=>{$('groups').querySelectorAll('input').forEach(input=>{input.checked=checked;});updateSelection();};
    $('discard').onclick=()=>{preview=null;$('preview').hidden=true;};
    $('reset').onclick=()=>{const p=prepareSettingsTransfer(api.defaults(),api.current(),api.defaults());renderPreview(p.values,'Reset preferences','Choose the groups to restore to their defaults. Bookmarks and profiles change only if you select them.');};
    $('import').onchange=async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>512*1024)throw Error('Settings files must be smaller than 512 KB.');const p=prepareSettingsTransfer(JSON.parse(await file.text()),api.current(),api.defaults());renderPreview(p.values,'Review settings import',`${p.changed.length} groups differ. ${p.ignored.length} unsupported or session-only groups will be ignored.`);}catch(error){notice(error.message);}};
    $('apply').onclick=async()=>{
      if(busy||!preview)return;const values={};for(const input of $('groups').querySelectorAll('input:checked'))values[input.value]=preview.values[input.value];if(!Object.keys(values).length)return;
      busy=true;updateSelection();try{await api.apply(values,preview.before);notice('Selected settings saved. Reload the game to ensure every feature uses the new preferences.');$('preview').hidden=true;preview=null;}catch(error){notice(error.message);}finally{busy=false;updateSelection();}
    };
    show(initialTab==='settings'?'settings':'tasks');if(initialTab==='settings')$('search').focus();
    void refresh(true);timer=setInterval(refresh,2000);
