// Presets contain preferences only: never targets, requests, credentials or a run command.
const OPERATION_PRESET_FIELDS=Object.freeze({
  transportSweep:['delayMs','maxPerRun','backgroundFirst'],
  dispatchRecruitment:['dispatchId','buildingTypeId','hiringPhase','personnelDesired','delayMs'],
  allianceCourses:['day','shareDuration','delayMs'],
  expansionPlanner:['dispatchId','buildingTypeId','operationKind','creditBudget','maxStations','delayMs'],
  stationIconCopier:['dispatchId','sourceBuildingId','replaceMode','delayMs']
});
function validateOperationPresets(value){
  if(!value||value.schema!==1||!Array.isArray(value.items)||value.items.length>25)throw Error('Unsupported preset collection.');
  const ids=new Set();
  const items=value.items.map(item=>{
    if(!item||typeof item.id!=='string'||!/^[a-zA-Z0-9_-]{1,64}$/.test(item.id)||ids.has(item.id))throw Error('Invalid preset identity.');ids.add(item.id);
    if(typeof item.name!=='string'||!item.name.trim()||item.name.length>60||!Object.hasOwn(OPERATION_PRESET_FIELDS,item.group))throw Error('Invalid preset name or tool.');
    if(!item.values||typeof item.values!=='object'||Array.isArray(item.values))throw Error('Invalid preset preferences.');
    const values={};for(const [key,v]of Object.entries(item.values)){
      if(!OPERATION_PRESET_FIELDS[item.group].includes(key)||!['string','number','boolean'].includes(typeof v)||(typeof v==='string'&&v.length>160)||(typeof v==='number'&&!Number.isFinite(v)))throw Error('Unsafe preset preference.');values[key]=v;
    }
    return {id:item.id,name:item.name.trim(),group:item.group,values};
  });return {schema:1,items};
}
function createOperationPresetControls(api,group){
  const host=document.createElement('details');host.className='mcms-operation-presets';
  host.innerHTML='<summary>Saved presets</summary><p>Presets prepare preferences only. Load the current stations, scan and review before running.</p><label>Preset name <input type="text" maxlength="60" placeholder="For example: Fire recruitment"></label><button type="button" data-preset="save">Save current choices</button><label>Saved preset <select aria-label="Saved operation preset"></select></label><p data-preset-preview></p><button type="button" data-preset="apply" disabled>Apply preferences only</button><button type="button" data-preset="delete" disabled>Delete preset…</button><div><button type="button" data-preset="export">Export presets</button><label>Import presets <input type="file" accept=".json,application/json" data-preset-file></label></div><p role="status" data-preset-notice></p>';
  const select=host.querySelector('select'),input=host.querySelector('input[type="text"]'),preview=host.querySelector('[data-preset-preview]'),notice=host.querySelector('[data-preset-notice]');
  const buttons=Object.fromEntries([...host.querySelectorAll('[data-preset]')].map(b=>[b.dataset.preset,b]));let items=[],busy=false;
  const selected=()=>items.find(item=>item.id===select.value);
  const render=()=>{const item=selected();buttons.apply.disabled=buttons.delete.disabled=busy||!item;buttons.save.disabled=busy;select.disabled=input.disabled=busy;preview.textContent=item?Object.entries(item.values).map(([k,v])=>k.replace(/([A-Z])/g,' $1')+': '+String(v)).join(' · '):'Choose a preset to preview its preferences.';};
  const load=()=>{const previous=select.value;items=validateOperationPresets(api.load()).items.filter(item=>item.group===group);select.replaceChildren(new Option('Choose a preset…',''),...items.map(item=>new Option(item.name,item.id)));select.value=previous;render();};
  const perform=async run=>{if(busy)return;busy=true;render();try{await run();load();}catch(error){notice.textContent=error.message;}finally{busy=false;render();}};
  host.addEventListener('click',e=>e.stopPropagation());host.addEventListener('keydown',e=>e.stopPropagation());select.onchange=render;
  buttons.save.onclick=()=>perform(async()=>{
    const name=input.value.trim();if(!name)throw Error('Give this preset a name first.');
    const all=validateOperationPresets(api.load());if(all.items.length>=25)throw Error('You have 25 presets. Delete an unused preset first.');
    const values={};for(const key of OPERATION_PRESET_FIELDS[group])if(api.current()[group]?.[key]!==undefined)values[key]=api.current()[group][key];
    all.items.push({id:crypto.randomUUID(),name,group,values});await api.save(validateOperationPresets(all));input.value='';notice.textContent='Preset saved for this game account.';
  });
  buttons.apply.onclick=()=>perform(async()=>{const item=selected();if(!item)return;await api.apply(item);notice.textContent='Preferences applied. Load current stations if needed, then run a fresh scan. No game actions were started.';});
  buttons.delete.onclick=()=>perform(async()=>{const item=selected();if(!item||!window.confirm('Delete preset “'+item.name+'”? Your current settings will stay unchanged.'))return;const all=validateOperationPresets(api.load());all.items=all.items.filter(p=>p.id!==item.id);await api.save(all);notice.textContent='Preset deleted.';});
  buttons.export.onclick=()=>{try{const all=validateOperationPresets(api.load()),url=URL.createObjectURL(new Blob([JSON.stringify(all,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='Toolkit-operation-presets.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){notice.textContent=error.message;}};
  host.querySelector('[data-preset-file]').onchange=event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;void perform(async()=>{if(file.size>64*1024)throw Error('Preset files must be smaller than 64 KB.');const incoming=validateOperationPresets(JSON.parse(await file.text())),existing=validateOperationPresets(api.load());const ids=new Set(incoming.items.map(i=>i.id));const merged=validateOperationPresets({schema:1,items:[...existing.items.filter(i=>!ids.has(i.id)),...incoming.items]});if(!window.confirm('Import '+incoming.items.length+' presets into this account? '+existing.items.filter(i=>ids.has(i.id)).length+' existing presets will be replaced. No settings or game actions will be applied.'))return;await api.save(merged);notice.textContent='Presets imported. Choose one to preview before applying preferences.';});};
  host.addEventListener('toggle',()=>{if(host.open&&!busy)try{load();}catch(error){notice.textContent=error.message;}});
  try{load();}catch(error){notice.textContent=error.message;}return host;
}

