    filterBar.append(filter,selectedLabel,button('Clear filter',()=>{filter.value='';selectedOnly.checked=false;filterFindings();}),selectionCount,el('small','Filtering here does not change selections. Existing selection buttons keep their original scope and can include hidden matches.'));
    if(resultHost)resultHost.before(filterBar);
