      for(const row of rows){const checked=Boolean(row.querySelector('input[type=checkbox]')?.checked),show=(!query||row.textContent.toLowerCase().includes(query))&&(!selectedOnly.checked||checked);row.classList.toggle('mcms-finding-filtered',!show);row.classList.toggle('mcms-row-selected',checked);if(show)visible++;if(checked){selected++;if(!show)hiddenSelected++;}}
