    const resultSummary=el('p'),resultList=el('div'),recovery=el('p','Review skipped or failed items below, correct their cause, then scan again. Successful actions are never replayed automatically.');const failures=button('Show failed items',()=>{for(const group of resultList.querySelectorAll('details'))group.open=group.dataset.failed==='true';resultList.querySelector('[data-failed=true]')?.scrollIntoView?.({block:'nearest'});});const rescan=button('Return to scan before retrying',()=>{scan.scrollIntoView?.({block:'start'});scan.querySelector('button')?.focus({preventScroll:true});});results.append(resultSummary,failures,rescan,resultList,recovery,button('View task centre',()=>api.tasks()));
    const guide=el('details',null,'mcms-operation-help');guide.append(el('summary','How this tool works & safeguards'));
    // Move original nodes, preserving inputs, selection state and delegated actions.
    const rows=Array.from(card.querySelectorAll('.mcms-row')).filter(row=>row.querySelector('[data-setting]'));
    for(const row of rows){const key=row.querySelector('[data-setting]').dataset.setting;( /delay|transport-sweep-mode|transport-sweep-max/.test(key)?advanced:choose).append(row);}
    const actionButtons=Array.from(card.querySelectorAll('button[data-action]')).filter(b=>!resultHost?.contains(b));
    for(const action of actionButtons){const key=action.dataset.action;
      if(key===definition[5]){action.textContent=definition[0]==='co-admin-patient-transport-sweep'?'Scan alliance patient transports':definition[0]==='alliance-courses'?'Scan eligible academies':'Scan selected scope';scan.append(action);}
      else if(key===definition[4])run.append(action);
      else if(key.startsWith('load-')){action.textContent=key==='load-station-icons'?'Load your stations':'Load dispatch centres';choose.append(action);}
      else if(key.startsWith('stop-')){action.textContent='Stop this operation';sticky.append(action);}
      else if(/^(select|clear)-/.test(key))selection.append(action);
      else guide.append(action);
    }
    if(api.presets){const groups={'co-admin-patient-transport-sweep':'transportSweep','dispatch-recruitment':'dispatchRecruitment','alliance-courses':'allianceCourses','expansion-and-upgrade-planner':'expansionPlanner','station-icon-copier':'stationIconCopier'};choose.prepend(createOperationPresetControls(api.presets,groups[definition[0]]));}
    choose.append(advanced);
    for(const child of original)if(child!==heading&&child!==resultHost&&card.contains(child))guide.append(child);
    shell.append(scope);shell.append(sticky,choose,scan,review,run,results,guide);
    card.append(shell);card.classList.add('mcms-operation-card');card.dataset.workflowReady='false';
    const record={card,tableSort:()=>({column:sortColumn,descending:sortDescending}),sortTable:column=>{sortDescending=sortColumn===column?!sortDescending:false;sortColumn=column;storeTable();record.lastResult='';refresh();},nextAction,failures,changeSummary,filterFindings,definition,steps,scope,choose,scan,review,findings,summary,run,runDescription,targetPreview,sticky,activity,progress,results,resultSummary,resultList,recovery,lastResult:'',reviewReady:false};cards.set(definition[0],record);
    card.addEventListener('change',()=>setTimeout(refresh,0));
