      const data=id===current||!api.runtime?api.snapshot(id):{runtime:api.runtime(id)},r=data.runtime||{},loading=Boolean(r.scanPromise||r.catalogPromise||r.preparing),running=Boolean(r.running),hasRun=Boolean(record.runScanAt!==undefined&&record.runScanAt===r.scannedAt&&!running||r.processed&&(record.runScanAt===undefined||record.runScanAt>=r.scannedAt)||r.lastReport&&(r.lastReport.completedAt||0)>=(r.scannedAt||0)),scanned=Boolean(r.scannedAt||r.queue?.length);
