      const scope=controls.map(control=>{const name=control.closest('.mcms-row')?.querySelector('.mcms-row-label')?.textContent||control.dataset.setting;const value=control.tagName==='SELECT'?control.selectedOptions[0]?.textContent:control.value;return name+': '+(value||'not chosen');}).join(' · ');
      setText(record.scope,(data.scope||'')+(scope?' · '+scope:''));
      setText(record.summary,needsFreshScan?'Scan again before another run. Review what changed and select only the work still needed.':scanned&&!data.count?'No eligible targets selected. Review the findings, adjust your scope or selection, then scan again if needed.':scanned?`${data.count} eligible / selected for the next run. ${data.detail||''}`:'No scan yet. Choose the scope, then scan to see what can be processed.');
      const findingsSignature=JSON.stringify([scanned,data.eligible,data.attention,data.excluded,data.reasons]);
      if(findingsSignature!==record.findingsSignature){record.findingsSignature=findingsSignature;const opened=new Set([...record.findings.querySelectorAll('details[open]')].map(n=>n.dataset.category));record.findings.replaceChildren();
        if(!scanned)record.findings.append(el('p','Findings will appear here, including the reasons items cannot be processed.'));
        else for(const [category,label]of [['eligible',data.eligibleLabel||'Eligible'],['attention','Needs attention'],['excluded','Excluded']]){
          const group=el('details');group.dataset.category=category;group.open=opened.has(category);group.append(el('summary',label+': '+(data[category]??data.count)));
          if(category==='eligible')group.append(el('p','Review the native findings and selection controls below. Eligibility is checked again before changes.'));
          const reasons=(data.reasons||[]).filter(reason=>reason.category===category);
          for(const reason of reasons){group.append(el('p',reason.label));if(reason.names?.length){const list=el('ul');for(const name of reason.names)list.append(el('li',String(name)));group.append(list);}}
          if(category!=='eligible'&&!reasons.length)group.append(el('p','None reported by this scan.'));
          record.findings.append(group);
        }
      }
      const changes=data.changes||[];const changeSignature=JSON.stringify([data.count,changes]);if(record.changeSignature!==changeSignature){record.changeSignature=changeSignature;record.changeSummary.replaceChildren();for(const [label,value]of [[data.countLabel||'Affected targets',String(data.count||0)],...changes])record.changeSummary.append(el('dt',label),el('dd',String(value)));}
      setText(record.runDescription,data.plan||'Review the scan before making changes.');
      const targets=data.targets||[],targetSignature=JSON.stringify(targets);
      if(record.targetSignature!==targetSignature){record.targetSignature=targetSignature;const list=record.targetPreview.querySelector('div');list.replaceChildren();for(const target of targets.slice(0,100))list.append(el('p',target));if(targets.length>100)list.append(el('p','Showing 100 of '+targets.length+' targets. The complete findings remain above.'));setText(record.targetPreview.querySelector('summary'),'Selected targets ('+targets.length+')');}
      record.targetPreview.hidden=!targets.length;
      const runButton=record.card.querySelector('[data-action="'+record.definition[4]+'"]');
      if(runButton){const text=record.definition[6]+(data.count?' ('+data.count+')':'');setText(runButton,text);runButton.dataset.reviewReady=String(record.reviewReady);}
      setText(record.activity,running?(r.stopRequested?'Stopping after the current request…':r.currentItem||'Operation running…'):loading?'Scanning / loading — no changes are being made.':hasRun?'Run finished. Review the results below.':'Ready when you are.');
      const nextTarget=running?record.card.querySelector('[data-action^="stop-"]'):!scanned||needsFreshScan?record.scan.querySelector('button'):record.reviewReady?runButton:record.review.querySelector('input,button');record.nextAction._target=nextTarget;record.nextAction.disabled=loading||!nextTarget;setText(record.nextAction,loading?'Scanning…':running?'Go to Stop':!scanned||needsFreshScan?'Go to Scan':record.reviewReady?'Review & run ('+data.count+')':'Review selection');record.card.setAttribute('aria-busy',String(loading));
