  if(v.data.kind==='alliance'){for(const type of ['daily','monthly'])nav.append(link(type==='daily'?'Daily contributions':'Monthly contributions','/verband/kasse?type='+type));const type=url.searchParams.get('type')==='monthly'?'monthly':'daily',scroll=Number(url.searchParams.get('scroll')||0);nav.append(link('Previous period','/verband/kasse?type='+type+'&scroll='+(scroll-1)),link('Current period','/verband/kasse?type='+type));if(scroll<0)nav.append(link('Next period','/verband/kasse?type='+type+'&scroll='+(scroll+1)));}
  if(v.data.kind==='overview'){
    const label=make('label','Compare completed periods: '),select=make('select');select.dataset.compareDays='';
    const choices=[1,3,7,14,30];for(const n of choices){const o=make('option',String(n));o.value=n;select.append(o);}
    v.compareSpan=choices.filter(n=>!v.data.invalid&&financeHistoryStats(financeCompletedHistory(v),n).comparison).filter(n=>n<=7).at(-1)||1;
    select.value=String(v.compareSpan);select.addEventListener('change',()=>{v.compareSpan=Number(select.value);render(v);});label.append(select);nav.append(label);
    const panel=make('section');panel.dataset.periodComparison='';panel.setAttribute('role','status');panel.setAttribute('aria-live','polite');nav.after(panel);
    v.updateComparison=()=>{
      const days=financeCompletedHistory(v);for(const o of select.options){const n=Number(o.value);o.disabled=!!v.data.invalid||!financeHistoryStats(days,n).comparison;o.textContent=n+' day'+(n===1?'':'s')+' vs previous '+n+(o.disabled?' — needs '+(n*2)+' complete days':'');}
      const comparison=v.data.invalid?null:financeHistoryStats(days,v.compareSpan).comparison;panel.replaceChildren();
      panel.append(make('h2',v.compareSpan+' completed day'+(v.compareSpan===1?'':'s')+' vs the preceding '+v.compareSpan));
      if(!comparison){panel.append(make('p','Comparison unavailable: this selection needs '+(v.compareSpan*2)+' consecutive completed days ending yesterday. Today is excluded.'));return;}
      panel.append(make('p',comparison.currentRange.join(' — ')+' compared with '+comparison.previousRange.join(' — ')+' (UTC).'));
      const table=make('table');table.innerHTML='<thead><tr><th>Measure</th><th>Recent period</th><th>Previous period</th><th>Change</th></tr></thead>';const body=make('tbody'),money=n=>Math.round(n).toLocaleString('en-GB')+' CR';
      for(const key of ['income','spending','net']){const row=make('tr'),recent=comparison.currentTotals[key],previous=comparison.previousTotals[key],delta=recent-previous;for(const value of [key==='net'?'Net change':key[0].toUpperCase()+key.slice(1),money(recent),money(previous),(delta>0?'+':'')+money(delta)])row.append(make('td',value));body.append(row);}table.append(body);panel.append(table,make('p','Uses full-day totals, independent of the filters below. The chart continues to show all loaded dates.'));
    };
  }
  const more=button(d,'Load older entries',async()=>{if(v.moreBusy||!v.nextHref)return;const href=v.nextHref;if(v.loadedPages.has(href))return;v.moreBusy=true;more.disabled=true;const oldLabel=more.textContent;more.textContent='Loading…';try{const doc=await api.read(href),data=read(doc,href);if(!v.host.isConnected)return;if(data.kind!==v.data.kind||data.available===false||!data.rows.length)throw Error('No readable entries returned for that page.');v.loadedPages.add(href);const added=v.data.kind==='alliance'?data.rows.filter(r=>r.category==='alliance-spending'):data.rows;v.extraRows??=[];v.extraRows.push(...added);v.extraInvalid=(v.extraInvalid||0)+data.invalid;v.data.rows.push(...added);v.data.invalid+=data.invalid;v.nextHref=data.nextHref;v.remote=true;v.appended=true;v.error='';render(v);}catch(e){v.error=e.message;render(v);}finally{v.moreBusy=false;more.textContent=oldLabel;more.disabled=!v.nextHref;}});v.nextHref=v.data.nextHref;v.loadedPages=new Set([v.href]);more.hidden=!v.nextHref;$('[data-export]').before(more);v.moreButton=more;
  v.updateCategories();
