// Session-only observations: estimates never fetch or persist financial history.
const financeObservedHistory=new Map();
function financeCompletedHistory(v){return (v.data.days||[]).filter(d=>d.dateKey<financeUTCDate(v.readAt||Date.now()));}
function financeVisibleDays(v){
  const days=(v.data.days||[]).slice().sort((a,b)=>a.dateKey.localeCompare(b.dateKey));
  if(!v.showDays||!days.length)return days;
  const start=Date.parse(days.at(-1).dateKey+'T00:00:00Z')-(v.showDays-1)*86400000;
  return days.filter(d=>Date.parse(d.dateKey+'T00:00:00Z')>=start);
}
function financePercentChange(current,previous){
  if(previous===0)return current===0?'No change':'No percentage baseline';
  const pct=(current-previous)/Math.abs(previous)*100;
  return (pct>0?'+':'')+pct.toFixed(1)+'%';
}
function financeGoalEstimate(days,remaining,now=Date.now()){
  if(!(remaining>0))return null;
  const map=new Map(days.map(d=>[d.dateKey,d])),end=Date.parse(financeUTCDate(now)+'T00:00:00Z'),sample=[];
  for(let i=1;i<=14;i++){const day=map.get(financeUTCDate(end-i*86400000));if(!day)break;sample.push(day);}
  if(sample.length<3||sample.some(d=>!Number.isFinite(d.net)||d.net<=0))return null;
  return {fast:Math.ceil(remaining/Math.max(...sample.map(d=>d.net))),slow:Math.ceil(remaining/Math.min(...sample.map(d=>d.net))),count:sample.length,start:sample.at(-1).dateKey,end:sample[0].dateKey};
}
function installFinanceExperience(v,api,render,button){
  const {$,doc}=v,make=(tag,text)=>{const e=doc.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
  const kind=v.data.kind,overview=kind==='overview',ledger=['ledger','coins'].includes(kind);
  if(kind!=='alliance')installFinanceOriginalSwitch(v,button);
  v.showDays=0;v.chartSeries=new Set([0,1,2]);v.selectedDay=null;
  v.root.querySelector('section').dataset.financeKind=kind;
  $('h1').textContent=({daily:'Daily Credits summary',overview:'Credits history',ledger:'Credits transactions',coins:'Coins transactions',alliance:'Alliance funds'})[kind];
  for(const a of $('nav').querySelectorAll('a'))if(new URL(a.href).pathname===new URL(v.href).pathname)a.setAttribute('aria-current','page');
  const advanced=make('details'),summary=make('summary','Advanced filters');advanced.dataset.advancedFilters='';advanced.append(summary);
  const amounts=$('[data-min]').closest('.actions');amounts.before(advanced);advanced.append(amounts);
  const chips=make('div');chips.className='actions filter-chips';chips.dataset.filterChips='';advanced.before(chips);
  const insight=make('p');insight.dataset.insights='';$('[data-metrics]').after(insight);
  const metricsTitle=make('h2');metricsTitle.dataset.metricsTitle='';$('[data-metrics]').before(metricsTitle);
  if(overview){
    const comparisonDetails=make('details'),comparisonSummary=make('summary','Compare completed periods');comparisonDetails.dataset.comparisonDetails='';
    const panel=$('[data-period-comparison]');panel.before(comparisonDetails);comparisonDetails.append(comparisonSummary,$('[data-compare-days]').parentElement,panel);
    v.query='';v.min='';v.max='';v.categories=[];v.selected=null;
    $('[data-search]').closest('.actions').hidden=true;advanced.hidden=true;
    const label=make('label','Show days: '),select=make('select');select.dataset.showDays='';
    for(const [value,text] of [[7,'7 days'],[14,'14 days'],[0,'All available']]){const o=make('option',text);o.value=value;select.append(o);}select.value='0';
    select.addEventListener('change',()=>{v.showDays=Number(select.value);v.selectedDay=null;render(v);});label.append(select);$('[data-date-navigation]').prepend(label);
    const today=make('section');today.dataset.todaySnapshot='';$('nav').before(today);
  }else{
    // Keep page-specific ordering useful; saved explicit choices remain respected.
    if(ledger&&!api.preference('filters_'+kind)){v.sort='date';$('[data-sort]').value='date';}
    if(ledger)for(const option of [...$('[data-sort]').options])if(['count','average'].includes(option.value))option.remove();
    if(ledger&&!['value','name','date'].includes(v.sort)){v.sort='date';$('[data-sort]').value='date';}
    if(kind==='daily')$('[data-sort] option[value="date"]')?.remove();
    if(kind==='daily'&&v.sort==='date'){v.sort='value';$('[data-sort]').value='value';}
  }
  v.updateExperience=()=>{
    const unavailable=v.data.available===false,days=financeVisibleDays(v),money=n=>Math.round(n).toLocaleString('en-GB')+v.unit;
    const filters=!!(v.query||v.min||v.max||v.categories.length||v.selected);
    chips.replaceChildren();
    const chip=(text,clear)=>chips.append(button(doc,text+' ×',()=>{clear();v.page=0;v.saveFilters();render(v);}));
    if(v.query)chip('Search: '+v.query,()=>{v.query='';$('[data-search]').value='';});
    for(const key of ['min','max'])if(v[key])chip((key==='min'?'Minimum: ':'Maximum: ')+v[key],()=>{v[key]='';$('[data-'+key+']').value='';});
    for(const key of v.categories)chip([...$('[data-multi]').options].find(o=>o.value===key)?.textContent||key,()=>{v.categories=v.categories.filter(k=>k!==key);});
    if(v.selected)chip('Category: '+(nativeCreditGroups(v.data.rows).find(g=>g.key===v.selected)?.label||v.selected),()=>v.selected=null);
    chips.hidden=overview||!filters;
    const status=$('[data-status]'),stale=financeUTCDate(v.readAt||Date.now())!==financeUTCDate(Date.now());status.dataset.warning=String(unavailable||!!v.data.invalid||!!v.error||stale);
    if(!unavailable&&!v.data.invalid&&!v.error)status.textContent=(overview?(days.length?days[0].dateKey+' — '+days.at(-1).dateKey+' UTC · '+days.length+' of '+v.data.days.length+' days available':'No dates available'):v.data.label)+' · Read from game '+new Date(v.readAt||Date.now()).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC'+(ledger?' · Loaded pages only':'');
    if(stale)status.append(' · Read before UTC midnight; reload the game view for current totals.');
    $('[data-full-totals]').hidden=overview||(!filters&&kind!=='alliance');
    metricsTitle.textContent=overview?'Shown dates · includes today if available':filters?'Matching results':kind==='daily'?'Selected day':ledger?'Loaded transactions':'Selected contribution period';
    const fourth=$('[data-metrics]').children[3];
    if(fourth){fourth.querySelector('span').textContent=overview?'Days available':ledger?'Transactions loaded':kind==='alliance'?'Entries shown':'Transactions';if(overview)fourth.querySelector('strong').textContent=unavailable?'Unavailable':String(days.length);}
    if(overview){
      $('[data-charts]').hidden=true;$('[data-groups]').parentElement.hidden=true;
      $('[data-detail]').hidden=true;$('[data-export]').parentElement.querySelector('summary').textContent='Export shown dates';
      const account=String(api.accountId?.()||'unknown');if(account!=='unknown')financeObservedHistory.set(account,v.data.invalid||unavailable||v.data.inferredDates?[]:(v.data.days||[]).filter(d=>d.dateKey<financeUTCDate(v.readAt||Date.now())).map(d=>({...d})));
      const today=(v.data.days||[]).find(d=>d.dateKey===financeUTCDate(Date.now())),snapshot=$('[data-today-snapshot]');snapshot.replaceChildren(make('h2','Today · '+financeUTCDate(Date.now())+' UTC · in progress'));
      if(today&&!v.data.invalid){const cards=make('div');cards.className='metrics';for(const [label,value] of [['Income',today.revenue],['Spending',Math.abs(today.spending)],['Net change',today.net]]){const card=make('div');card.append(make('span',label),make('strong',money(value)));cards.append(card);}snapshot.append(cards);}else snapshot.append(make('p','Today’s figures are unavailable in the current game data.'));
      const timeline=$('[data-timeline]');timeline.replaceChildren(financeRenderTimeline(doc,days));
      financeInteractiveChart(v,days,make,button);
      const source=timeline.firstElementChild,table=source?.querySelector('table');
      if(table){const chartPane=make('div'),tablePane=make('div');chartPane.className='finance-chart-pane';tablePane.className='finance-table-pane';tablePane.append(make('h2','Daily figures · newest first'),table);chartPane.append(...source.childNodes);source.className='finance-history-grid';source.append(chartPane,tablePane);}
      const complete=days.filter(d=>d.dateKey<financeUTCDate(v.readAt||Date.now())),stats=financeHistoryStats(complete,1);
      insight.textContent=complete.length?'Completed days shown: '+complete[0].dateKey+' — '+complete.at(-1).dateKey+' UTC · Best completed day: '+stats.best.dateKey+' ('+money(stats.best.net)+' net) · Average completed-day income: '+money(stats.average)+'.':'No completed days in this view.';
      if(v.data.inferredDates)insight.append(' Dates inferred from the game’s oldest-to-newest rows ending today.');
      // Comparisons use full available history independently of the display range.
      const comparison=v.data.invalid?null:financeHistoryStats(financeCompletedHistory(v),v.compareSpan).comparison,panel=$('[data-period-comparison]');
      if(comparison){for(const [i,key] of ['income','spending','net'].entries()){
        const row=panel.querySelectorAll('tbody tr')[i],recent=comparison.currentTotals[key],previous=comparison.previousTotals[key];
        row.lastElementChild.append(make('small',' · '+financePercentChange(recent,previous)));
        const max=Math.max(1,Math.abs(recent),Math.abs(previous));for(const [j,value] of [recent,previous].entries()){const bar=make('span');bar.className='comparison-bar';bar.style.width=(Math.abs(value)/max*100)+'%';bar.setAttribute('aria-hidden','true');row.children[j+1].append(bar);}
      }panel.lastElementChild.textContent='Today is excluded. Comparison uses all available completed dates; Show days only changes the chart, table and totals below.';}
    }else{
      const totals=nativeCreditTotals(v.rows),spenders=nativeCreditGroups(v.rows).filter(g=>g.total<0).sort((a,b)=>a.total-b.total);
      insight.textContent=(filters?'Matching results':'Current view')+' · '+(spenders.length?'Largest spending category: '+spenders[0].label+' ('+money(-spenders[0].total)+'). ':'No spending recorded. ')+(kind==='alliance'?'Contributions and spending cover separate periods.':totals.income>0?'Spending offset '+(totals.spending/totals.income*100).toFixed(1)+'% of income.':'No income baseline for a spending ratio.');
      if(ledger){$('[data-charts]').hidden=true;$('[data-groups]').parentElement.hidden=true;$('[data-detail]').parentElement.open=true;$('[data-detail]').parentElement.querySelector('summary').textContent='Transactions and exports';
        for(const tr of $('[data-detail]').querySelectorAll('tr')){tr.children[4]?.remove();tr.children[3]?.remove();}
      }
    }
    insight.hidden=unavailable;metricsTitle.hidden=unavailable;v.syncOriginal?.();
  };
}
function installFinanceOriginalSwitch(v,button){
  const {doc,host,$}=v,marked=new Set(),style=doc.createElement('style');
  style.textContent='[data-mcms-finance-source="hidden"]{display:none!important}';doc.head.append(style);
  const toggle=button(doc,'Show original view',()=>{v.showOriginal=!v.showOriginal;v.syncOriginal();});toggle.dataset.originalView='';$('header').append(toggle);
  v.syncOriginal=()=>{
    const hide=$('[data-enabled]').checked&&!v.showOriginal&&v.data.available!==false;
    for(const node of doc.querySelectorAll('table,canvas,svg,h1,.page-header')){
      if(host.contains(node)||node.contains(host))continue;
      let branch=node;
      while(branch.parentElement&&branch.parentElement!==doc.body&&!branch.parentElement.contains(host))branch=branch.parentElement;
      if(branch===doc.body||branch.contains(host))continue;
      marked.add(branch);
    }
    for(const nav of doc.querySelectorAll('nav,.navbar')){const links=[...nav.querySelectorAll('a[href]')];if(!nav.contains(host)&&links.length&&links.every(a=>/^\/(credits|coins)(\/|$)/.test(new URL(a.href,doc.URL).pathname)))marked.add(nav);}
    for(const node of marked){if(!node.isConnected){marked.delete(node);continue;}if(hide)node.setAttribute('data-mcms-finance-source','hidden');else node.removeAttribute('data-mcms-finance-source');}
    toggle.textContent=v.showOriginal?'Show Toolkit view':'Show original view';toggle.setAttribute('aria-pressed',String(!!v.showOriginal));
    $('[data-content]').hidden=!$('[data-enabled]').checked||!!v.showOriginal;
  };
  v.cleanupOriginal=()=>{style.remove();for(const node of marked)node.removeAttribute('data-mcms-finance-source');};
}
function financeInteractiveChart(v,days,make,button){
  const area=v.$('[data-timeline]'),svg=area.querySelector('svg');if(!svg)return;
  const names=['Income','Spending','Net'],controls=make('div');controls.className='actions chart-controls';
  names.forEach((name,i)=>{const label=make('label'),input=make('input');input.type='checkbox';input.checked=v.chartSeries.has(i);input.dataset.series=i;input.addEventListener('change',()=>{if(input.checked)v.chartSeries.add(i);else v.chartSeries.delete(i);paint();});label.append(input,' '+name);controls.append(label);});
  const label=make('label','Inspect day: '),select=make('select');select.dataset.inspectDay='';
  for(const d of days.slice().reverse()){const option=make('option',d.dateKey+(d.dateKey===financeUTCDate(Date.now())?' · Today':''));option.value=d.dateKey;select.append(option);}label.append(select);controls.append(label);svg.before(controls);
  const tooltip=make('p','Select a day to see exact figures.');tooltip.dataset.chartReadout='';tooltip.setAttribute('aria-live','polite');svg.after(tooltip);
  const rows=[...area.querySelectorAll('tbody tr')],bars=[...svg.querySelectorAll('rect')].filter(r=>r.querySelector('title'));
  function choose(key){v.selectedDay=key;select.value=key;const d=days.find(d=>d.dateKey===key);if(!d)return;tooltip.textContent=key+' UTC · Income '+d.revenue.toLocaleString('en-GB')+' CR · Spending '+Math.abs(d.spending).toLocaleString('en-GB')+' CR · Net '+d.net.toLocaleString('en-GB')+' CR';for(const row of rows)row.classList.toggle('finance-selected',row.firstElementChild.textContent.startsWith(key));}
  function paint(){bars.forEach((b,i)=>{b.style.display=v.chartSeries.has(i%3)?'':'none';});}
  select.addEventListener('change',()=>choose(select.value));svg.setAttribute('role','group');svg.setAttribute('aria-label','Daily chart. Choose a day or tap a column to inspect exact figures.');
  const ns=svg.namespaceURI,step=660/days.length;
  days.forEach((d,i)=>{const hit=v.doc.createElementNS(ns,'rect');for(const [key,value] of Object.entries({x:20+i*step,y:8,width:step,height:199,fill:'transparent',role:'button',tabindex:0,'aria-label':'Inspect '+d.dateKey}))hit.setAttribute(key,value);hit.addEventListener('click',()=>choose(d.dateKey));hit.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();choose(d.dateKey);}});svg.append(hit);
    if(d.dateKey!==financeUTCDate(Date.now())&&(i===0||i===days.length-1||i%Math.max(1,Math.ceil(days.length/4))===0)){const text=v.doc.createElementNS(ns,'text');text.setAttribute('x',20+i*step+step*.42);text.setAttribute('y','224');text.setAttribute('text-anchor','middle');text.setAttribute('fill','#c8c2b6');text.setAttribute('font-size','11');text.textContent=d.dateKey.slice(5);svg.append(text);}
  });
  for(const row of rows){row.tabIndex=0;const key=row.firstElementChild.textContent.slice(0,10);row.addEventListener('click',()=>choose(key));row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(key);}});}
  choose(days.some(d=>d.dateKey===v.selectedDay)?v.selectedDay:days.at(-1).dateKey);paint();
}

function financeRankRows(doc){
  return [...doc.querySelectorAll('table tbody tr')].map(tr=>{
    const cells=[...tr.children],headers=[...tr.closest('table').querySelectorAll('thead th')],index=headers.findIndex(h=>/credits|required|earned/i.test(h.textContent));
    const candidates=cells.filter(c=>/^[\s\d,.'’]+(?:\s*Credits)?$/i.test(c.textContent.trim())&&/\d/.test(c.textContent));
    const number=index>=0?cells[index]:candidates.length===1?candidates[0]:null,name=cells.find(c=>c!==number&&/[a-z]/i.test(c.textContent)&&!/^\s*[\d,.]+\s*Credits\s*$/i.test(c.textContent));
    return number&&name?{threshold:nativeCreditNumber(number.textContent),name:name.textContent.trim()}:null;
  }).filter(r=>r&&r.threshold!==null).sort((a,b)=>a.threshold-b.threshold);
}
function installMoneyMenu(api){
  let host,wrapper,root,observer,timer,dead=false,busy=false,account=null,at=0,ranks=null,previousBalance=null,goals=[],goalStarts={},accountKey='unknown';
  const number=n=>n===null||n===undefined||!Number.isFinite(Number(n))?null:Number(n),format=n=>number(n)===null?'Unavailable':Math.round(n).toLocaleString('en-GB');
  function save(){api.savePreference('goals_'+accountKey,JSON.stringify(goals));}
  function readGoals(){try{const v=JSON.parse(api.preference('goals_'+accountKey)||'[]');goals=Array.isArray(v)?v.filter(n=>Number.isSafeInteger(n)&&n>0).slice(0,20).sort((a,b)=>a-b):[];}catch{goals=[];}try{const saved=JSON.parse(api.preference('goal_starts_'+accountKey)||'{}');goalStarts=saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{};}catch{goalStarts={};}}
  function balances(){return {credits:api.balance('credits')??number(account?.credits_user_current),coins:api.balance('coins')??number(account?.coins_user_current)};}
  function render(){if(!root)return;const b=balances(),$=s=>root.querySelector(s);$('[data-values]').textContent='Credits '+format(b.credits)+' · Coins '+format(b.coins);const total=number(account?.credits_user_total);$('[data-lifetime]').textContent='Lifetime earned: '+format(total)+' Credits';
    const next=total===null?null:ranks?.find(r=>r.threshold>total);$('[data-rank]').textContent=next?'Next rank: '+next.name+' · '+format(next.threshold-total)+' Credits remaining':ranks?.length&&total!==null?'Highest listed rank reached':'Open Rank details for your next rank';
    $('[data-rank-progress]').hidden=!next;if(next){$('[data-rank-progress]').max=next.threshold;$('[data-rank-progress]').value=total;}
    const position=number(account?.user_toplist_position),top=$('[data-toplist]');top.textContent='Leaderboard: '+(position&&position>0?'#'+format(position):'View position');top.href=position&&position>0?'/toplist?page='+Math.ceil(position/20):'/toplist';
    $('[data-alliance]').textContent=account?.credits_alliance_active?'Alliance funds: '+format(account.credits_alliance_current)+' · lifetime '+format(account.credits_alliance_total):'Alliance funds: open game view';
    const target=goals.find(n=>b.credits!==null&&n>b.credits),reached=goals.filter(n=>b.credits!==null&&n<=b.credits);$('[data-goals]').textContent=goals.length?'Targets: '+goals.map(format).join(' · ')+(target?' — '+format(target-b.credits)+' to next target':' — all reached'):'No savings targets set';$('[data-goal-progress]').hidden=!target;if(target){$('[data-goal-progress]').max=target;$('[data-goal-progress]').value=b.credits;}
    const progress=$('[data-goal-detail]');progress.replaceChildren();
    if(target){const start=goalStarts[target],baseline=number(start?.balance);if(baseline!==null&&Number.isFinite(start?.at)){const gain=b.credits-baseline;progress.textContent='Since '+financeUTCDate(start.at)+': '+(gain>0?'+':'')+format(gain)+' Credits toward this target. ';}
      const estimate=financeGoalEstimate(financeObservedHistory.get(accountKey)||[],target-b.credits);
      progress.append(estimate?'Estimated '+estimate.fast+'–'+estimate.slow+' days remaining if daily net stays within the observed range ('+estimate.start+' — '+estimate.end+' UTC, '+estimate.count+' completed days). Spending and play time can change this.':'Estimate unavailable. View Daily history; at least 3 consecutive completed days with positive net gains are needed.');
    }
    if(previousBalance!==null&&b.credits!==null&&goals.some(n=>previousBalance<n&&b.credits>=n)){$('summary').dataset.reached='true';$('[data-notice]').textContent='Savings target reached: '+reached.map(format).join(' · ');}
    previousBalance=b.credits;$('[data-freshness]').textContent=at?'Account details refreshed '+new Date(at).toLocaleTimeString()+'; balances follow the game.':'Balances from the game. Open to load account details.';
    const sale=api.sale?.();$('[data-sale]').textContent=sale?'Coin sale: '+sale:'';
  }
  async function refresh(force=false){if(busy||dead||(!force&&at&&Date.now()-at<300000))return;busy=true;root.querySelector('[data-error]').textContent='Refreshing account details…';try{const data=await api.account();if(dead)return;account=data;const id=String(data.user_id||api.accountId?.()||'unknown');if(id!==accountKey){accountKey=id;readGoals();root.querySelector('[data-input]').value=goals.join(', ');previousBalance=null;}at=Date.now();root.querySelector('[data-error]').textContent='';render();if(!ranks){try{ranks=financeRankRows(await api.ranks());if(!dead)render();}catch{}}}catch(e){if(!dead)root.querySelector('[data-error]').textContent=e.message;}finally{busy=false;}}
  function mount(){if(dead||host?.isConnected)return;const anchor=document.querySelector('#navigation_top,.credits-value');if(!anchor)return;host=document.createElement('div');host.id='mcms-money-menu';wrapper=anchor.closest('li')?document.createElement('li'):host;if(wrapper!==host)wrapper.append(host);(anchor.closest('li')||anchor).after(wrapper);root=host.attachShadow({mode:'open'});root.innerHTML='<style>:host{position:relative;display:inline-block;font:14px/1.5 system-ui;color:#ededed}summary{cursor:pointer;padding:10px;background:#131313;border-radius:6px;list-style:none}summary[data-reached=true]{outline:3px solid #ededed}.body{position:fixed;right:12px;top:65px;z-index:2147483000;box-sizing:border-box;width:min(390px,calc(100vw - 24px));max-height:75vh;overflow:auto;background:#050505;border:1px solid #7c7c7c;border-radius:10px;padding:16px;box-shadow:0 8px 30px #0008}a{color:#ededed;display:inline-block;padding:8px}button,input{font:inherit;padding:8px;border-radius:5px;border:1px solid #939393;background:#131313;color:inherit;min-height:40px}input{width:100%;box-sizing:border-box}progress{width:100%;accent-color:#ededed}p{margin:8px 0}small{color:#ededed}:focus-visible{outline:3px solid #ededed}[hidden]{display:none!important}</style><details><summary>Money</summary><div class="body"><strong data-values></strong><p data-lifetime></p><p data-rank></p><progress data-rank-progress hidden></progress><nav><a href="/credits/daily">Daily summary</a><a href="/credits/overview">History</a><a href="/credits">Transactions</a><a href="/coins/list">Coins history</a><a href="/coins">Coins / offers</a><a href="/level">Rank details</a><a data-toplist href="/toplist"></a><a href="/verband/kasse">Alliance funds</a></nav><p data-alliance></p><p data-sale></p><label>Savings targets (Credits, separated by commas)<input data-input placeholder="1000000, 5000000" inputmode="text"></label><button type="button" data-save>Save targets</button><button type="button" data-reset>Clear targets</button><p data-goals></p><progress data-goal-progress hidden></progress><p data-goal-detail></p><p data-notice role="status"></p><button type="button" data-refresh>Refresh account details</button><p data-error role="status"></p><small data-freshness></small></div></details>';
    if(api.styleUrl){const theme=document.createElement('link');theme.rel='stylesheet';theme.href=api.styleUrl;root.append(theme);}
    accountKey=String(api.accountId?.()||'unknown');readGoals();root.querySelector('[data-input]').value=goals.join(', ');root.querySelector('details').addEventListener('toggle',()=>{if(root.querySelector('details').open){delete root.querySelector('summary').dataset.reached;render();refresh();}});
    root.querySelector('[data-refresh]').onclick=()=>refresh(true);root.querySelector('[data-save]').onclick=()=>{const parts=root.querySelector('[data-input]').value.split(',').map(x=>x.trim()).filter(Boolean);if(parts.length>20||parts.some(x=>!/^\d+$/.test(x)||!Number.isSafeInteger(Number(x))||Number(x)<=0)){root.querySelector('[data-notice]').textContent='Use up to 20 positive whole-number targets, separated by commas.';return;}goals=[...new Set(parts.map(Number))].sort((a,b)=>a-b);const balance=balances().credits;goalStarts=Object.fromEntries(goals.map(n=>[n,goalStarts[n]||(balance===null?null:{balance,at:Date.now()})]));api.savePreference('goal_starts_'+accountKey,JSON.stringify(goalStarts));save();render();root.querySelector('[data-notice]').textContent='Targets saved.';};root.querySelector('[data-reset]').onclick=()=>{goals=[];goalStarts={};api.savePreference('goal_starts_'+accountKey,'{}');root.querySelector('[data-input]').value='';root.querySelector('[data-notice]').textContent='';delete root.querySelector('summary').dataset.reached;save();render();};
    root.addEventListener('click',e=>{const a=e.target.closest('a');if(a){e.preventDefault();api.open(a.getAttribute('href'));root.querySelector('details').open=false;}});render();
  }
  observer=new MutationObserver(records=>{if(host&&records.every(r=>host.contains(r.target)))return;clearTimeout(timer);timer=setTimeout(()=>{mount();render();},200);});observer.observe(document.documentElement,{childList:true,subtree:true,characterData:true});mount();
  return {destroy(){dead=true;clearTimeout(timer);observer.disconnect();wrapper?.remove();}};
}

// ==UserScript==
// @name         MissionChief Map Command Toolkit
// @namespace    https://github.com/Conroy1988/missionchief-map-command-toolkit
