        dockWidth,
        launchWidth: safeLaunchWidth,
        contentWidth,
        groupWidth: Math.max(1, ...groupWidths),
        groupWidths,
        groupColumns,
        groupButtonColumns,
        pinColumns,
        pinWidth,
        pinsInline,
        naturalFilterHeight,
        naturalPinHeight,
        filterMaxHeight,
        pinMaxHeight,
        pinMargin,
        scrollFallback: naturalHeight > safeHeight,
