    function updateMissionAgeLabels() { const enabled=Boolean(state.missionAge&&state.visibility.myMissions);if(!enabled){clearMissionAgeLabels();return;}if(deferMapInteractionRefresh())return;scanInlineMissionMarkerData(true);installMissionMarkerAddHook();const map=findLeafletMapInstance(false);if(!map||!pageWindow.L||typeof pageWindow.L.layerGroup!=='function'||typeof pageWindow.L.marker!=='function'||typeof pageWindow.L.divIcon!=='function'){clearMissionAgeLabels();if(!document.hidden)scheduleMissionAgeRefresh(700);return;}const floatPane=ensureMissionFloatPane(map);if(!floatPane){clearMissionAgeLabels();if(!document.hidden)scheduleMissionAgeRefresh(700);return;}let markers=getMissionMarkerIndex().markers;if(!markers.length){invalidateMarkerRegistryCaches('mission');markers=getMissionMarkerIndex().markers;}const economyBounds=state.economyMode?economyPaddedBounds(map,0.08):null,activeMissionIds=new Set(),now=Date.now();let candidates=0,rendered=0,missingEvidence=0;try{if(!missionAgeGroup||missionAgeGroup._map!==map){clearMissionAgeLabels();missionAgeGroup=pageWindow.L.layerGroup();missionAgeGroup.__mcmsMissionAgeLayer=true;missionAgeGroup.addTo(map);}for(const marker of markers){const missionId=normaliseMissionId(marker?.mission_id??marker?.missionId??marker?.options?.mission_id??marker?.options?.missionId);if(missionId===null)continue;if(!missionKnownPersonal(marker,missionId)){if(!missionHasExplicitAllianceOwner(marker,missionId))missingEvidence+=1;continue;}candidates+=1;const existingLabel=missionAgeLabels.get(missionId);let latLng;try{latLng=marker.getLatLng?.();}catch(error){latLng=null;}if(!latLng||(economyBounds&&!economyBounds.contains?.(latLng)))continue;try{const onMap=typeof map.hasLayer==='function'?map.hasLayer(marker):Boolean(marker._map);if(!onMap){if(existingLabel)activeMissionIds.add(missionId);continue;}}catch(error){if(existingLabel)activeMissionIds.add(missionId);continue;}let createdAt=getMissionCreatedAt(marker,missionId);if(createdAt===null){captureMissionMarkerData(marker);createdAt=getMissionCreatedAt(marker,missionId);}if(createdAt===null){missingEvidence+=1;if(existingLabel)activeMissionIds.add(missionId);continue;}const ageMs=Math.max(0,now-createdAt),ageText=formatMissionAge(createdAt,now),severity=missionAgeSeverity(ageMs);activeMissionIds.add(missionId);let label=existingLabel;const attached=Boolean(label&&typeof missionAgeGroup.hasLayer==='function'&&missionAgeGroup.hasLayer(label));if(!label||!attached){if(label)try{missionAgeGroup.removeLayer(label);}catch(error){}label=pageWindow.L.marker(latLng,{interactive:false,keyboard:false,bubblingMouseEvents:false,pane:floatPane,zIndexOffset:0,icon:makeMissionAgeIcon(ageText,severity)});label.__mcmsMissionAgeLabel=true;label.__mcmsMissionAgeText=ageText;label.__mcmsMissionAgeSeverityRank=severity.rank;label.__mcmsMissionAgeCreatedAt=createdAt;label.__mcmsMissionAgeSourceMarker=marker;label.addTo(missionAgeGroup);missionAgeLabels.set(missionId,label);}else{try{label.setLatLng(latLng);}catch(error){}label.__mcmsMissionAgeSourceMarker=marker;if(label.__mcmsMissionAgeText!==ageText||label.__mcmsMissionAgeSeverityRank!==severity.rank||label.__mcmsMissionAgeCreatedAt!==createdAt){label.__mcmsMissionAgeText=ageText;label.__mcmsMissionAgeSeverityRank=severity.rank;label.__mcmsMissionAgeCreatedAt=createdAt;try{label.setIcon(makeMissionAgeIcon(ageText,severity));}catch(error){}}}rendered+=1;}for(const[missionId,label]of missionAgeLabels.entries()){if(activeMissionIds.has(missionId))continue;missionAgeLabels.delete(missionId);try{missionAgeGroup.removeLayer(label);}catch(error){}}const plan=missionAgeRefreshPlan({enabled,moving:false,mapReady:true,markers:markers.length,candidates:candidates+missingEvidence,labels:rendered});if(!document.hidden)scheduleMissionAgeRefresh(plan.delay);}catch(error){clearMissionAgeLabels();if(!document.hidden)scheduleMissionAgeRefresh(1000);} }

    function scheduleMissionAgeRefresh(delay = 220) {
        if (deferMapInteractionRefresh()) return;
        runtimeClearTimeout(missionAgeTimer);
        missionAgeTimer = runtimeSetTimeout(updateMissionAgeLabels, state.economyMode ? Math.max(700, delay) : delay);
    }

    function missionAgeSeverity(ageMs) {
        const age = Math.max(0, Number(ageMs) || 0);
        if (age >= 24 * 60 * 60 * 1000) return { rank: 3, label: '24H+ CRITICAL', className: 'mcms-age-critical' };
        if (age >= 16 * 60 * 60 * 1000) return { rank: 2, label: '16H+ HIGH', className: 'mcms-age-high' };
        if (age >= 8 * 60 * 60 * 1000) return { rank: 1, label: '8H+ AGED', className: 'mcms-age-aged' };
        return { rank: 0, label: 'RECENT', className: 'mcms-age-recent' };
    }

    function missionKnownPersonal(marker, missionId) {
        const id = normaliseMissionId(missionId);
        if (!marker || id === null) return false;
        if (isPersonalMissionLayer(marker, id)) return true;
        const overlay = missionOverlayData.get(id);
        const currentUserId = currentUserIdCached();
        if (currentUserId !== null && overlay?.userId !== undefined && String(overlay.userId) === currentUserId) return true;
        if (liveMissionSnapshots.get(id)?.source === 'personal') return true;
        return false;
    }


    function clearUnitCommitmentLabels() {
        if (unitCommitmentGroup) {
        try { unitCommitmentGroup.clearLayers(); unitCommitmentGroup.remove(); } catch (err) {}
        }
        unitCommitmentLabels.clear();
        unitCommitmentGroup = null;
    }

    function unitCommitmentAnchor(marker, missionId) {
        const personal = isPersonalMissionLayer(marker, missionId);
        let rowsAbove = 0;
        if (personal) {
        if (state.missionAge) rowsAbove += 1;
        } else if (state.allianceCredits) rowsAbove += 1;
        return 18 + (rowsAbove * 20);
    }

    function makeUnitCommitmentIcon(commitment, personal, anchor) {
        const text = commitment.onScene && commitment.travelling
        ? `${commitment.onScene}✓ ${commitment.travelling}→`
        : commitment.onScene ? `${commitment.onScene}✓` : commitment.travelling ? `${commitment.travelling}→` : `U ${commitment.total}`;
        return pageWindow.L.divIcon({
        className: 'mcms-unit-commitment-icon',
        html: `<span class="mcms-unit-commitment-badge ${personal ? 'mcms-unit-personal' : 'mcms-unit-alliance'}">${escapeHtml(text)}</span>`,
        iconSize: [0, 0], iconAnchor: [0, anchor]
        });
    }

    function updateUnitCommitmentLabels() {
        if (deferMapInteractionRefresh()) return;
        if (!state.unitCommitment) { clearUnitCommitmentLabels(); return; }
        const vehicleDataFreshnessMs = state.economyMode ? 5 * 60 * 1000 : VEHICLE_API_REFRESH_MS;
        if (!vehicleApiReady || Date.now() - vehicleApiLastFetch >= vehicleDataFreshnessMs) refreshPersonalVehicleData(false);
        const map = findLeafletMapInstance(false);
        if (!map || !pageWindow.L || typeof pageWindow.L.layerGroup !== 'function' || typeof pageWindow.L.marker !== 'function' || typeof pageWindow.L.divIcon !== 'function') {
        clearUnitCommitmentLabels(); return;
        }
        const floatPane = ensureMissionFloatPane(map);
        if (!floatPane) { clearUnitCommitmentLabels(); return; }
        const economyBounds = state.economyMode ? economyPaddedBounds(map, 0.08) : null;
        try {
        if (!unitCommitmentGroup || unitCommitmentGroup._map !== map) {
            clearUnitCommitmentLabels();
            unitCommitmentGroup = pageWindow.L.layerGroup();
            unitCommitmentGroup.__mcmsUnitCommitmentLayer = true;
            unitCommitmentGroup.addTo(map);
        }
        const activeIds = new Set();
        for (const marker of getMissionMarkerIndex().markers) {
            const missionId = normaliseMissionId(marker?.mission_id ?? marker?.missionId ?? marker?.options?.mission_id ?? marker?.options?.missionId);
            if (missionId === null) continue;
            const personal = isPersonalMissionLayer(marker, missionId);
            if (personal && !state.visibility.myMissions) continue;
            if (!personal && !state.visibility.allianceMissions) continue;
            const commitment = personalUnitCommitmentForMission(missionId);
            if (commitment.total <= 0) continue;
            let latLng = null;
            try { latLng = marker.getLatLng?.() || null; } catch (err) {}
            if (!latLng || (economyBounds && !economyBounds.contains?.(latLng))) continue;
            const anchor = unitCommitmentAnchor(marker, missionId);
            const signature = `${commitment.total}:${commitment.onScene}:${commitment.travelling}:${personal}:${anchor}`;
            activeIds.add(missionId);
            let label = unitCommitmentLabels.get(missionId);
            if (!label) {
                label = pageWindow.L.marker(latLng, { interactive:false, keyboard:false, bubblingMouseEvents:false, pane:floatPane, zIndexOffset:0, icon:makeUnitCommitmentIcon(commitment, personal, anchor) });
                label.__mcmsUnitCommitmentSignature = signature;
                label.__mcmsUnitCommitmentLabel = true;
                label.addTo(unitCommitmentGroup);
                unitCommitmentLabels.set(missionId, label);
            } else {
                try { label.setLatLng(latLng); } catch (err) {}
                if (label.__mcmsUnitCommitmentSignature !== signature) {
                    label.__mcmsUnitCommitmentSignature = signature;
                    try { label.setIcon(makeUnitCommitmentIcon(commitment, personal, anchor)); } catch (err) {}
                }
            }
        }
        for (const [missionId, label] of unitCommitmentLabels.entries()) {
            if (activeIds.has(missionId)) continue;
            unitCommitmentLabels.delete(missionId);
            try { unitCommitmentGroup.removeLayer(label); } catch (err) {}
        }
        } catch (err) { clearUnitCommitmentLabels(); }
    }

    function scheduleUnitCommitmentRefresh(delay = 400) {
        if (deferMapInteractionRefresh()) return;
        runtimeClearTimeout(unitCommitmentTimer);
        unitCommitmentTimer = runtimeSetTimeout(updateUnitCommitmentLabels, state.economyMode ? Math.max(900, delay) : delay);
    }


    function clearTransportWatcherLabels() {
        if (transportWatcherGroup) {
        try { transportWatcherGroup.clearLayers(); transportWatcherGroup.remove(); } catch (err) {}
        }
        transportWatcherLabels.clear();
        transportWatcherGroup = null;
    }

    function transportRequirementFromSnapshot(snapshot) {
        const raw = normaliseMissingRequirementText(snapshot?.missingText);
        if (!raw) return null;
        const text = raw.toLowerCase();
        const transportRequired = [
        /\btransport(?:ation)?\b.{0,34}\b(?:needed|required|waiting|pending)\b/i,
        /\b(?:needs?|requires?|awaiting)\b.{0,34}\btransport(?:ation)?\b/i,
        /\bmust be transported\b/i,
        /\btransport is needed\b/i,
        /\b(?:transport|abtransport|gefangenentransport)\b.{0,34}\b(?:erforderlich|ben[oö]tigt|notwendig)\b/i,
        /\b(?:muss|müssen)\b.{0,34}\btransportiert werden\b/i,
        /\b(?:transport|vervoer)\b.{0,34}\b(?:nodig|vereist)\b/i,
            /\b(?:moet|moeten)\b.{0,34}\b(?:vervoerd|afgevoerd)\b/i
        ].some(pattern => pattern.test(text));
        if (!transportRequired) return null;

        const prisonerTerms = /prison|prisoner|custod|detainee|arrest|cell|jail|gefangen|haft|arrestant|gevangen/i;
        const patientTerms = /patient|hospital|ambulance|medical|casualt|injur|verletz|krankenhaus|ziekenhuis|gewond/i;
        const patients = Number(snapshot?.patientsCount) || 0;
        const prisoners = Number(snapshot?.prisonersCount) || 0;
        let type = 'general';
        if (prisonerTerms.test(text) || (prisoners > 0 && patients <= 0)) type = 'prisoner';
        else if (patientTerms.test(text) || (patients > 0 && prisoners <= 0)) type = 'patient';

        const explicitCount = raw.match(/\b(\d{1,2})\b/);
        let count = explicitCount ? Number(explicitCount[1]) : 0;
        if (!count && type === 'patient' && patients > 1) count = patients;
        if (!count && type === 'prisoner' && prisoners > 1) count = prisoners;
        count = Math.min(99, Math.max(0, Math.round(count || 0)));

        return {
        type,
        count,
        label: type === 'patient' ? 'Patient transport required' : type === 'prisoner' ? 'Prisoner transport required' : 'Transport required'
        };
    }

    function transportWatcherSvg(type) {
        if (type === 'prisoner') {
        return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 8.5h12.2l3.1 3.3v5.1H3.5z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M15.7 8.5v3.3h3.1M7 11.2v3.2M10 11.2v3.2M13 11.2v3.2" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round"/><circle cx="7.1" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/><circle cx="16.4" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/></svg>`;
        }
        if (type === 'patient') {
        return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 8.5h11.8l3.7 3.5v4.9H3.5z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M15.3 8.5V12H19M8.3 10.2v4.3M6.15 12.35h4.3" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round"/><circle cx="7.1" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/><circle cx="16.4" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/></svg>`;
        }
        return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.8 8.8h11.9l3.7 3.4v4.7H2.8z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M14.7 8.8v3.4h3.7M7.4 12.7h5.1M10.8 10.8l2 1.9-2 1.9" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round"/><circle cx="6.5" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/><circle cx="15.8" cy="18" r="1.7" fill="#171008" stroke="currentColor" stroke-width="1.3"/></svg>`;
    }

    function renderedMissionFloatWidth(label, selector, fallback) {
        try {
        const badge = label?._icon?.querySelector?.(selector);
        const width = Number(badge?.getBoundingClientRect?.().width);
        if (Number.isFinite(width) && width > 0) return width;
        } catch (err) {}
        return fallback;
    }

    function transportWatcherPlacement(map, marker, missionId, requirement) {
        const personal = isPersonalMissionLayer(marker, missionId);
        let occupiedWidth = 0;
        let source = 'marker';

        if (personal && state.missionAge) {
        occupiedWidth = renderedMissionFloatWidth(
            missionAgeLabels.get(missionId),
            '.mcms-mission-age-badge',
            52
        );
        source = 'mission-age';
        } else if (!personal && state.allianceCredits) {
        occupiedWidth = renderedMissionFloatWidth(
            allianceCreditLabels.get(missionId),
            '.mcms-alliance-credit-badge',
            64
        );
        source = 'alliance-credit';
        } else if (state.unitCommitment) {
        const commitment = personalUnitCommitmentForMission(missionId);
        if (commitment.total > 0) {
            occupiedWidth = renderedMissionFloatWidth(
                unitCommitmentLabels.get(missionId),
                '.mcms-unit-commitment-badge',
                54
            );
            source = 'unit-count';
        }
        }

        const watcherHalfWidth = 13;
        const gap = occupiedWidth > 0 ? 6 : 4;
        const horizontalOffset = occupiedWidth > 0
        ? Math.ceil((occupiedWidth / 2) + watcherHalfWidth + gap)
        : 21;

        let side = 'right';
        try {
        const latLng = marker?.getLatLng?.();
        const point = latLng && map?.latLngToContainerPoint?.(latLng);
        const size = map?.getSize?.();
        const countExtra = Number(requirement?.count) > 1 ? 10 : 3;
        if (point && size && point.x + horizontalOffset + watcherHalfWidth + countExtra > size.x - 4) side = 'left';
        } catch (err) {}

        return {
        side,
        source,
        horizontalOffset,
        iconAnchor: [side === 'right' ? -horizontalOffset : horizontalOffset, 18],
        signature: `${side}:${source}:${horizontalOffset}`
        };
    }

    function makeTransportWatcherIcon(requirement, placement) {
        const type = ['patient', 'prisoner'].includes(requirement?.type) ? requirement.type : 'general';
        const side = placement?.side === 'left' ? 'left' : 'right';
        const count = Number(requirement?.count) > 1 ? `<span class="mcms-transport-watcher-count">${escapeHtml(requirement.count)}</span>` : '';
        return pageWindow.L.divIcon({
        className: 'mcms-transport-watcher-icon',
        html: `<span class="mcms-transport-watcher-badge mcms-transport-${type} mcms-transport-side-${side}" aria-label="${escapeHtml(requirement?.label || 'Transport required')}" title="${escapeHtml(requirement?.label || 'Transport required')}">${transportWatcherSvg(type)}${count}</span>`,
        iconSize: [0, 0],
        iconAnchor: placement?.iconAnchor || [-21, 18]
        });
    }

    function updateTransportWatcherLabels() {
        if (deferMapInteractionRefresh()) return;
        runtimeClearTimeout(transportWatcherTimer);
        transportWatcherTimer = null;
        if (!state.transportWatcher) {
        clearTransportWatcherLabels();
        return;
        }

        const map = findLeafletMapInstance(false);
        if (!map || !pageWindow.L || typeof pageWindow.L.layerGroup !== 'function' || typeof pageWindow.L.marker !== 'function' || typeof pageWindow.L.divIcon !== 'function') {
        clearTransportWatcherLabels();
        return;
        }
        const pane = ensureMissionFloatPane(map);
        if (!pane) {
        clearTransportWatcherLabels();
        return;
        }
        const economyBounds = state.economyMode ? economyPaddedBounds(map, 0.08) : null;

        try {
        if (!transportWatcherGroup || transportWatcherGroup._map !== map) {
            clearTransportWatcherLabels();
            transportWatcherGroup = pageWindow.L.layerGroup();
            transportWatcherGroup.__mcmsTransportWatcherLayer = true;
            transportWatcherGroup.addTo(map);
        }

        const activeIds = new Set();
        const now = Date.now();
        for (const marker of getMissionMarkerIndex().markers) {
            const missionId = normaliseMissionId(marker?.mission_id ?? marker?.missionId ?? marker?.options?.mission_id ?? marker?.options?.missionId);
            if (missionId === null) continue;
            const personal = isPersonalMissionLayer(marker, missionId);
            if (personal && !state.visibility.myMissions) continue;
            if (!personal && !state.visibility.allianceMissions) continue;

            const snapshot = liveMissionSnapshots.get(missionId) || missionSnapshotFromMarker(marker, now);
            const requirement = transportRequirementFromSnapshot(snapshot);
            if (!requirement) continue;

            let latLng = null;
            try { latLng = marker.getLatLng?.() || null; } catch (err) {}
            if (!latLng || (economyBounds && !economyBounds.contains?.(latLng))) continue;
            try {
                const onMap = typeof map.hasLayer === 'function' ? map.hasLayer(marker) : Boolean(marker._map);
                if (!onMap) continue;
            } catch (err) {}

            const placement = transportWatcherPlacement(map, marker, missionId, requirement);
            const signature = `${requirement.type}:${requirement.count}:${requirement.label}:${placement.signature}`;
            activeIds.add(missionId);
            let label = transportWatcherLabels.get(missionId);
            if (!label) {
                label = pageWindow.L.marker(latLng, {
                    interactive: false, keyboard: false, bubblingMouseEvents: false,
                    pane, zIndexOffset: 0, icon: makeTransportWatcherIcon(requirement, placement)
                });
                label.__mcmsTransportWatcherSignature = signature;
                label.__mcmsTransportWatcherLabel = true;
                label.addTo(transportWatcherGroup);
                transportWatcherLabels.set(missionId, label);
                if (requirement.type === 'patient') emitToolkitNotification('patient', requirement.label || `Mission ${missionId}`, { dedupeKey: String(missionId) });
            } else {
                try { label.setLatLng(latLng); } catch (err) {}
                if (label.__mcmsTransportWatcherSignature !== signature) {
                    label.__mcmsTransportWatcherSignature = signature;
                    try { label.setIcon(makeTransportWatcherIcon(requirement, placement)); } catch (err) {}
                }
            }
        }

        for (const [missionId, label] of transportWatcherLabels.entries()) {
            if (activeIds.has(missionId)) continue;
            transportWatcherLabels.delete(missionId);
            try { transportWatcherGroup.removeLayer(label); } catch (err) {}
        }
        } catch (err) {
        clearTransportWatcherLabels();
        }
    }

    function scheduleTransportWatcherRefresh(delay = 320) {
        if (deferMapInteractionRefresh()) return;
        runtimeClearTimeout(transportWatcherTimer);
        transportWatcherTimer = runtimeSetTimeout(updateTransportWatcherLabels, state.economyMode ? Math.max(900, delay) : delay);
    }

    function transportSweepSleep(ms) {
        return runtimeDelay(ms);
    }

    function normaliseTransportSweepReport(value) {
        let source = value;
        if (typeof source === 'string') {
        try { source = JSON.parse(source); } catch (err) { return null; }
        }
        if (!source || typeof source !== 'object' || Array.isArray(source)) return null;
        const sweepId = String(source.sweepId || '').trim();
        const outcome = String(source.outcome || '').trim();
        const completedAt = Math.max(0, Number(source.completedAt) || 0);
        if (!/^sweep-\d{10,16}-[a-z0-9]{6}$/u.test(sweepId) || !['successful', 'partial', 'failed', 'manually-stopped'].includes(outcome) || !completedAt) return null;
        const number = input => Math.max(0, Math.round(Number(input) || 0));
        const missionsChecked = number(source.missionsChecked);
        const eligibleMissions = number(source.eligibleMissions);
        const missionsCompleted = Math.min(eligibleMissions, number(source.missionsCompleted));
        const cleared = number(source.cleared);
        const skipped = number(source.skipped);
        const errors = number(source.errors);
        const processed = number(source.processed);
        const successRate = processed ? Math.round((cleared / processed) * 100) : 0;
        const rawDiscord = source.discord && typeof source.discord === 'object' ? source.discord : {};
        const discordStatus = ['not-configured', 'sending', 'sent', 'failed'].includes(rawDiscord.status) ? rawDiscord.status : 'not-configured';
        const discordMessage = String(rawDiscord.message || '').trim().slice(0, 180);
        return Object.freeze({
        schemaVersion: 1,
        sweepId,
        toolkitVersion: String(source.toolkitVersion || SCRIPT.version).trim().slice(0, 24),
        startedAt: Math.max(0, Number(source.startedAt) || 0),
        completedAt,
        durationMs: Math.min(86400000, Math.max(0, Number(source.durationMs) || 0)),
        outcome,
        missionsChecked,
        eligibleMissions,
        missionsCompleted,
        cleared,
        skipped,
        errors,
        processed,
        successRate,
        discord: Object.freeze({
            status: discordStatus,
            message: discordMessage,
            sentAt: Math.max(0, Number(rawDiscord.sentAt) || 0)
        })
        });
    }

    function loadTransportSweepReport() {
        const report = normaliseTransportSweepReport(gmGetValueSafe(SCRIPT.transportSweepReportState, ''));
        if (!report || report.discord.status !== 'sending') return report;
        return normaliseTransportSweepReport({
        ...report,
        discord: { status: 'failed', message: 'Delivery was interrupted before Discord confirmed receipt.', sentAt: 0 }
        });
    }

    function persistTransportSweepReport(report) {
        const clean = normaliseTransportSweepReport(report);
        if (!clean) return false;
        return gmSetValueSafe(SCRIPT.transportSweepReportState, JSON.stringify(clean));
    }

    function setTransportSweepReport(report, { render = true } = {}) {
        const clean = normaliseTransportSweepReport(report);
        if (!clean) return null;
        transportSweepRuntime.lastReport = clean;
        transportSweepRuntime.hudFinal = true;
        persistTransportSweepReport(clean);
        if (render) renderTransportSweepPanel();
        return clean;
    }

    function dismissTransportSweepReport({ quiet = false, render = true } = {}) {
        transportSweepRuntime.lastReport = null;
        transportSweepRuntime.hudFinal = false;
        gmDeleteValueSafe(SCRIPT.transportSweepReportState);
        removeTransportSweepHud();
        if (render) renderTransportSweepPanel();
        if (!quiet) showToast('Patient Transport Sweep report dismissed');
    }

    function transportSweepOutcomeMeta(outcome) {
        if (outcome === 'successful') return { label: 'Successful', tone: 'complete', colour: 0x46e58b };
        if (outcome === 'failed') return { label: 'Failed', tone: 'error', colour: 0xff646c };
        if (outcome === 'manually-stopped') return { label: 'Manually stopped', tone: 'stopped', colour: 0x95a5a6 };
        return { label: 'Partial', tone: 'partial', colour: 0xffb648 };
    }

    function transportSweepDiscordMeta(){return {label:'Discord: Review to send',tone:'neutral',retryLabel:'Prepare Discord report'};}

    function formatTransportSweepDuration(durationMs) {
        const totalSeconds = Math.max(0, Math.round((Number(durationMs) || 0) / 1000));
        const hours = Math.floor(totalSeconds / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;
        if (hours) return `${hours}h ${String(minutes).padStart(2, '0')}m ${String(seconds).padStart(2, '0')}s`;
        return `${minutes}m ${String(seconds).padStart(2, '0')}s`;
    }

    function createTransportSweepReport(wasStopped, missionProgress) {
        const completedAt = Date.now();
        const cleared = Math.max(0, Number(transportSweepRuntime.cleared) || 0);
        const skipped = Math.max(0, Number(transportSweepRuntime.skipped) || 0);
        const errors = Math.max(0, Number(transportSweepRuntime.errors) || 0);
        const processed = Math.max(0, Number(transportSweepRuntime.processed) || 0);
        const outcome = wasStopped ? 'manually-stopped'
        : errors > 0 && cleared === 0 ? 'failed'
        : errors > 0 || skipped > 0 ? 'partial'
        : 'successful';
        const webhookConfigured = Boolean(getDiscordWebhookUrl());
        return normaliseTransportSweepReport({
        schemaVersion: 1,
        sweepId: `sweep-${completedAt}-${Math.random().toString(36).slice(2, 8).padEnd(6, '0')}`,
        toolkitVersion: SCRIPT.version,
        startedAt: Math.max(0, Number(transportSweepRuntime.startedAt) || completedAt),
        completedAt,
        durationMs: Math.max(0, completedAt - (Number(transportSweepRuntime.startedAt) || completedAt)),
        outcome,
        missionsChecked: transportSweepRuntime.missionsChecked,
        eligibleMissions: missionProgress.total,
        missionsCompleted: missionProgress.completed,
        cleared,
        skipped,
        errors,
        processed,
        discord: {
            status: webhookConfigured ? 'sending' : 'not-configured',
            message: webhookConfigured ? 'Posting aggregate sweep statistics…' : 'Open Discord integrations in the extension popup to send this report.',
            sentAt: 0
        }
        });
    }

    function updateTransportSweepReportDiscord(sweepId, discord) {
        const current = transportSweepRuntime.lastReport;
        if (!current || current.sweepId !== sweepId) return null;
        return setTransportSweepReport({ ...current, discord: { ...current.discord, ...discord } });
    }

    function transportSweepElementVisible(element) {
        if (!element || !element.isConnected) return false;
        try {
        const view = element.ownerDocument?.defaultView || window;
        const style = view.getComputedStyle(element);
        if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity) === 0) return false;
        const rect = element.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
        } catch (err) {
        return false;
        }
    }

    async function transportSweepWaitFor(...args){return pilotInvokeFeature("administration","transportSweepWaitFor",{get Date(){return typeof Date==='undefined'?undefined:Date},set Date(value){Date=value},get runtime(){return typeof runtime==='undefined'?undefined:runtime},set runtime(value){runtime=value},get transportSweepRuntime(){return typeof transportSweepRuntime==='undefined'?undefined:transportSweepRuntime},set transportSweepRuntime(value){transportSweepRuntime=value},get transportSweepSleep(){return typeof transportSweepSleep==='undefined'?undefined:transportSweepSleep},set transportSweepSleep(value){transportSweepSleep=value}},args);}

    function transportSweepLog(message, level = 'info') {
        const clean = String(message || '').trim();
        if (!clean) return;
        transportSweepRuntime.statusMessage = clean;
        transportSweepRuntime.statusLevel = String(level || 'info');
        transportSweepRuntime.log.unshift({ time: Date.now(), message: clean, level });
        if (transportSweepRuntime.log.length > 18) transportSweepRuntime.log.length = 18;
        renderTransportSweepPanel();
    }

    function transportSweepMissionIdFromListEntry(entry) {
        if (!entry) return null;
        const explicit = entry.getAttribute?.('mission_id') ?? entry.getAttribute?.('data-mission-id') ?? entry.getAttribute?.('data-mission_id');
        const idMatch = String(entry.id || '').match(/^mission_(\d+)$/u);
        let hrefMatch = null;
        try {
            const href = entry.matches?.('a[href*="/missions/"]') ? entry.getAttribute('href') : entry.querySelector?.('a[href*="/missions/"]')?.getAttribute('href');
            hrefMatch = String(href || '').match(/\/missions\/(\d+)(?:\/|$|[?#])/u);
        } catch (err) {}
        const missionId = normaliseMissionId(explicit ?? idMatch?.[1] ?? hrefMatch?.[1]);
        return /^\d+$/u.test(String(missionId || '')) ? missionId : null;
    }

    function transportSweepMissionListOwnership(entry) {
        if (!entry) return 'unknown';
        const list = entry.closest?.('[id^="mission_list"]');
        const listId = String(list?.id || '').toLowerCase();
        const ownerId = entry.getAttribute?.('user_id') ?? entry.getAttribute?.('data-user-id') ?? entry.getAttribute?.('data-user_id')
            ?? list?.getAttribute?.('user_id') ?? list?.getAttribute?.('data-user-id') ?? list?.getAttribute?.('data-user_id');
        const currentUserId = currentMissionUserId();
        if (ownerId !== undefined && ownerId !== null && ownerId !== '' && currentUserId !== null) {
            return String(ownerId) === currentUserId ? 'personal' : 'alliance';
        }
        if (/^mission_list_alliance(?:_|$)/u.test(listId)) return 'alliance';
        if (listId === 'mission_list' || /^mission_list_(?:sicherheitswache|event)(?:_|$)/u.test(listId)) return 'personal';
        const signal = `${entry.className || ''} ${list?.className || ''} ${entry.getAttribute?.('data-mission-source') || ''} ${entry.getAttribute?.('data-source') || ''}`.toLowerCase();
        return /(?:^|[\s_-])(?:alliance|verband|association)(?:$|[\s_-])/u.test(signal) ? 'alliance' : 'unknown';
    }

    function transportSweepMissionListRecord(entry) {
        const missionId = transportSweepMissionIdFromListEntry(entry);
        if (missionId === null || entry.classList?.contains('mission_deleted')) return null;
        const ownership = transportSweepMissionListOwnership(entry);
        const patientCountNode = entry.querySelector?.('.mission_list_patient_icon + strong, [data-patients-count], [data-patients_count]');
        const rawPatientCount = patientCountNode?.getAttribute?.('data-patients-count') ?? patientCountNode?.getAttribute?.('data-patients_count') ?? patientCountNode?.textContent;
        const patientCountMatch = String(rawPatientCount || '').match(/\d+/u);
        const patientsCount = patientCountMatch ? Number(patientCountMatch[0]) : null;
        const entryText = String(entry.textContent || '').replace(/\s+/g, ' ').trim();
        const patientSignal = Boolean(
            entry.querySelector?.('.mission_list_patient_icon, [id^="mission_patient_summary_"], [id^="mission_patients_"], .mission_patient, [data-patients-count], [data-patients_count]')
            || /\b(?:patient|casualt|injur|ambulance|hospital|transport)\b/i.test(entryText)
        );
        const missingNode = entry.querySelector?.('[data-missing-text], [data-missing_text], .missing_text');
        const rawMissingText = missingNode?.getAttribute?.('data-missing-text') ?? missingNode?.getAttribute?.('data-missing_text') ?? missingNode?.textContent ?? '';
        const missingTextKnown = Boolean(missingNode);
        const captionNode = entry.querySelector?.('.mission_caption, .mission-caption, .panel-title, a[href*="/missions/"]');
        const caption = normaliseMissionCaption(captionNode?.textContent || entry.getAttribute?.('mission_caption') || entry.getAttribute?.('data-mission-caption') || '');
        const createdAt = parseMissionTimestamp(entry.getAttribute?.('created_at') ?? entry.getAttribute?.('data-created-at') ?? entry.getAttribute?.('data-created_at')) || 0;
        return {
            missionId,
            ownership,
            caption,
            createdAt,
            patientsCount,
            prisonersCount: null,
            patientSignal,
            missingText: normaliseMissingRequirementText(rawMissingText),
            missingTextKnown
        };
    }

    function captureTransportSweepMissionListDataFromDocument(doc) {
        const records = new Map();
        let entries = [];
        try {
            entries = Array.from(doc?.querySelectorAll?.([
                '#missions-panel-body .missionSideBarEntry',
                '[id^="mission_list"] .missionSideBarEntry',
                '[id^="mission_list"] [mission_id]',
                '[id^="mission_list"] [data-mission-id]',
                '[id^="mission_list"] [data-mission_id]',
                '[id^="mission_list"] [id^="mission_"]'
            ].join(', ')) || []);
        } catch (err) {}
        for (const entry of entries) {
            const record = transportSweepMissionListRecord(entry);
            if (!record) continue;
            const previous = records.get(record.missionId);
            if (!previous) {
                records.set(record.missionId, record);
                continue;
            }
            const ownership = [previous.ownership, record.ownership].includes('personal') ? 'personal'
                : [previous.ownership, record.ownership].includes('alliance') ? 'alliance' : 'unknown';
            records.set(record.missionId, {
                ...previous,
                ...record,
                ownership,
                caption: record.caption || previous.caption,
                createdAt: record.createdAt || previous.createdAt,
                patientsCount: record.patientsCount ?? previous.patientsCount,
                patientSignal: Boolean(previous.patientSignal || record.patientSignal),
                missingText: record.missingTextKnown ? record.missingText : previous.missingText,
                missingTextKnown: Boolean(previous.missingTextKnown || record.missingTextKnown)
            });
        }
        return records;
    }

    function transportSweepPatientRequestIdsFromDocument(doc) {
        const patientVehicleIds = new Set();
        const ownVehicleIds = new Set(Array.from(transportSweepRuntime.ownVehicleIds || [], id => String(id)));
        for (const id of personalVehicleApiCache.keys()) ownVehicleIds.add(String(id));
        const anchors = Array.from(doc?.querySelectorAll?.('a[href*="/vehicles/"]') || []);
        for (const anchor of anchors) {
            const href = String(anchor.getAttribute?.('href') || '');
            const vehicleId = href.match(/\/vehicles\/(\d+)(?:\/|$|[?#])/u)?.[1];
            if (!vehicleId || ownVehicleIds.has(vehicleId)) continue;
            const row = anchor.closest?.('tr[id^="vehicle_row_"], tr, li, [id^="vehicle_row_"], [class*="vehicle_row"]');
            if (!row?.querySelector?.('.building_list_fms_5')) continue;
            const vehicleTypeId = String(anchor.getAttribute?.('vehicle_type_id') || anchor.getAttribute?.('data-vehicle-type-id') || '');
            const text = `${anchor.textContent || ''} ${row.textContent || ''}`;
            if (vehicleTypeId !== '5' && !/ambulance|patient|paramedic|rettungs|krankentransport|rtw\b/i.test(text)) continue;
            patientVehicleIds.add(vehicleId);
        }

        const requestIds = new Set();
        const requestAnchors = Array.from(doc?.querySelectorAll?.([
            '.alert.alert-danger:not(.alert-missing-vehicles) a.btn.btn-success[href^="/vehicles/"]',
            '#mission_vehicle_at_mission a.btn.btn-success[href^="/vehicles/"]',
            '[data-transport-request="true"][data-transport-request-type="patient"] a[href^="/vehicles/"]'
        ].join(', ')) || []);
        for (const anchor of requestAnchors) {
            const href = String(anchor.getAttribute?.('href') || '');
            const vehicleId = href.match(/\/vehicles\/(\d+)(?:\/|$|[?#])/u)?.[1];
            if (vehicleId && patientVehicleIds.has(vehicleId)) requestIds.add(vehicleId);
        }
        return requestIds;
    }

    function transportSweepSnapshotFromMissionDocument(doc, record) {
        if (!doc || !record || record.ownership !== 'alliance') return null;
        const missingRoot = doc.getElementById?.('missing_text') || doc.querySelector?.('[data-requirement-type="vehicles"], [data-requirement-type="patients"], [data-requirement-type="prisoners"]')?.closest?.('div');
        const patientRequestIds = transportSweepPatientRequestIdsFromDocument(doc);
        const patientsCount = Math.max(Number(record.patientsCount) || 0, doc.querySelectorAll?.('.mission_patient, [id^="patient_"]')?.length || 0);
        const prisonersCount = doc.querySelectorAll?.('.mission_prisoner, [id^="prisoner_"]')?.length || 0;
        const caption = normaliseMissionCaption(doc.querySelector?.('#missionH1, h1')?.textContent || record.caption || '');
        const missingText = normaliseMissingRequirementText(missingRoot?.textContent || '');
        const missingRequirement = transportRequirementFromSnapshot({ missingText, patientsCount, prisonersCount });
        if (!patientRequestIds.size && missingRequirement?.type !== 'patient') return null;
        const requestCount = patientRequestIds.size || Math.max(1, Number(missingRequirement?.count) || patientsCount || 1);
        return {
            ...record,
            caption,
            patientsCount: requestCount,
            prisonersCount,
            missingText: patientRequestIds.size ? `Patient transport required (${requestCount})` : missingText,
            missingTextKnown: true
        };
    }

    function transportSweepPatientTimerEvidence() {
        let rawTimers = null;
        try { rawTimers = pageWindow.patient_timers; } catch (err) {}
        const timers = Array.isArray(rawTimers)
            ? rawTimers
            : rawTimers && typeof rawTimers === 'object' ? Object.values(rawTimers) : [];
        const missions = new Map();
        timers.forEach((timer, index) => {
            const params = timer?.params && typeof timer.params === 'object' ? timer.params : timer;
            const missionId = normaliseMissionId(params?.mission_id ?? params?.missionId);
            if (missionId === null) return;
            const patientId = String(params?.id ?? params?.patient_id ?? timer?.patient_id ?? `timer-${index}`);
            const missingText = normaliseMissingRequirementText(params?.missing_text ?? params?.missingText ?? '');
            const requirement = transportRequirementFromSnapshot({ missingText, patientsCount: 1, prisonersCount: 0 });
            const current = missions.get(missionId) || { patients: new Set(), transportPatients: new Set(), missingTexts: [] };
            current.patients.add(patientId);
            if (missingText) current.missingTexts.push(missingText);
            if (requirement?.type === 'patient') current.transportPatients.add(patientId);
            missions.set(missionId, current);
        });
        return { missions, timers: timers.length };
    }

    function hydrateTransportSweepPatientTimerMissions() {
        const evidence = transportSweepPatientTimerEvidence();
        let coveredMissions = 0;
        let transportMissions = 0;
        let transportPatients = 0;
        for (const [missionId, record] of missionProgressPageMissionRecords.entries()) {
            if (record?.ownership !== 'alliance' || !record.patientSignal) continue;
            const patientState = evidence.missions.get(String(missionId));
            if (!patientState?.patients?.size) continue;
            const expectedPatients = Math.max(0, Number(record.patientsCount) || 0);
            if (expectedPatients && patientState.patients.size < expectedPatients) continue;
            const requestCount = patientState.transportPatients.size;
            const missingText = requestCount
                ? `Patient transport required (${requestCount})`
                : patientState.missingTexts.join(' · ');
            missionProgressPageMissionRecords.set(String(missionId), {
                ...record,
                patientsCount: requestCount,
                prisonersCount: 0,
                missingText,
                missingTextKnown: true
            });
            coveredMissions += 1;
            if (requestCount) {
                transportMissions += 1;
                transportPatients += requestCount;
            }
        }
        return { ...evidence, coveredMissions, transportMissions, transportPatients };
    }

