    function transportSweepFallbackMissionIds(now = Date.now()) {
        const ids = new Set();
        if (missionProgressPageLastSuccessAt && now - missionProgressPageLastSuccessAt <= MISSION_PROGRESS_PAGE_REFRESH_MS * 2) {
            for (const missionId of missionProgressPageMissionIds) ids.add(String(missionId));
            for (const missionId of missionProgressPageMissionRecords.keys()) ids.add(String(missionId));
        }

        const roots = [];
        try { roots.push(...document.querySelectorAll('#missions, #missions-panel-body, [id^="mission_list"], .missions-panel, .mission-list')); } catch (err) {}
        for (const root of roots) {
            let entries = [];
            try { entries = Array.from(root.querySelectorAll('[id^="mission_"], [mission_id], [data-mission-id], [data-mission_id], a[href*="/missions/"]')); } catch (err) {}
            for (const entry of entries) {
                const missionId = transportSweepMissionIdFromListEntry(entry);
                if (missionId !== null) ids.add(missionId);
            }
        }
        return ids;
    }

    function transportSweepSnapshotFromOverlay(missionId) {
        const id = normaliseMissionId(missionId);
        if (id === null) return null;
        const overlay = missionOverlayData.get(id) || null;
        const pageRecord = missionProgressPageMissionRecords.get(id) || null;
        const overlayOwnership = overlay ? missionWatchOwnership(null, id, overlay) : 'personal';
        if (overlay?.userId && overlayOwnership !== 'alliance') return null;
        if (pageRecord?.ownership !== 'alliance' && overlayOwnership !== 'alliance') return null;
        const missingText = pageRecord?.missingTextKnown ? pageRecord.missingText : overlay?.missingText;
        const finiteNumber = value => value !== null && value !== undefined && value !== '' && Number.isFinite(Number(value)) ? Number(value) : null;
        return {
            missionId: id,
            caption: pageRecord?.caption || getMissionCaption(null, id) || `Alliance mission ${id}`,
            createdAt: pageRecord?.createdAt || getMissionCreatedAt(null, id) || 0,
            missingText: normaliseMissingRequirementText(missingText),
            patientsCount: finiteNumber(pageRecord?.patientsCount ?? overlay?.patientsCount),
            prisonersCount: finiteNumber(pageRecord?.prisonersCount ?? overlay?.prisonersCount),
            source: 'alliance',
            ownership: 'alliance'
        };
    }

    function transportSweepMissionRecords(now = Date.now()) {
        const records = [];
        const seen = new Set();
        for (const marker of getMissionMarkerIndex().markers) {
            const missionId = missionIdFromMarker(marker);
            if (missionId === null || seen.has(missionId)) continue;
            seen.add(missionId);
            const verified = missionProgressPageMissionRecords.get(String(missionId));
            const snapshot = verified?.transportVerified ? verified : liveMissionSnapshots.get(missionId) || missionSnapshotFromMarker(marker, now);
            if (snapshot) records.push({missionId, marker, snapshot, fallback: false});
        }
        for (const missionId of transportSweepFallbackMissionIds(now)) {
            if (seen.has(missionId)) continue;
            seen.add(missionId);
            const snapshot = transportSweepSnapshotFromOverlay(missionId);
            if (snapshot) records.push({missionId, marker: null, snapshot, fallback: true});
        }
        return records;
    }

    function buildTransportSweepQueue() {
        const now = Date.now();
        const queue = [];
        let missionsChecked = 0;
        for (const { missionId, marker, snapshot, fallback } of transportSweepMissionRecords(now)) {
        if (fallback ? snapshot.ownership !== 'alliance' : isPersonalMissionLayer(marker, missionId)) continue;
        missionsChecked += 1;
        const requirement = transportRequirementFromSnapshot(snapshot);
        const patientCount = Math.max(0, Number(snapshot?.patientsCount) || 0);
        if (!requirement || requirement.type === 'prisoner') continue;
        if (requirement.type !== 'patient' && patientCount <= 0) continue;
        const count = Math.max(1, Math.min(99, Number(requirement.count) || patientCount || 1));
        queue.push({
            missionId,
            caption: String(snapshot?.caption || `Alliance mission ${missionId}`),
            count,
            createdAt: Number(snapshot?.createdAt) || 0,
            requirement: requirement.label || 'Patient transport required'
        });
        }
        queue.sort((a, b) => (a.createdAt || Number.MAX_SAFE_INTEGER) - (b.createdAt || Number.MAX_SAFE_INTEGER));
        transportSweepRuntime.queue = queue;
        transportSweepRuntime.missionsChecked = missionsChecked;
        transportSweepRuntime.scannedAt = now;
        renderTransportSweepPanel();
        return queue;
    }

