    function dispatchRecruitmentSafeSkip(message) {
        const error = new Error(message);
        error.dispatchRecruitmentSafeSkip = true;
        return error;
    }

    function dispatchRecruitmentSafetyStop(message) {
        const error = new Error(`Dispatch Recruitment safety stop: ${message}`);
        error.dispatchRecruitmentFatal = true;
        return error;
    }

    function dispatchRecruitmentGuardMutation(href, body = '') {
        let url;
        try { url = new URL(href, document.baseURI || pageWindow.location.href); }
        catch (err) { throw dispatchRecruitmentSafeSkip('blocked a malformed native recruitment action'); }
        if (url.origin !== pageWindow.location.origin) throw dispatchRecruitmentSafeSkip('blocked an external native recruitment action');
        const parameterNames = [
            ...Array.from(url.searchParams.keys()),
            ...Array.from(new URLSearchParams(String(body || '')).keys())
        ];
        if (/\/leitstelle-set\//u.test(url.pathname) || parameterNames.some(name => /leitstelle|control[_ -]?cent(?:re|er)/iu.test(String(name)))) {
            throw dispatchRecruitmentSafetyStop('blocked a request that could modify a Dispatch Centre assignment. No request was sent.');
        }
        return url;
    }

    function dispatchRecruitmentAssertStationScope(record, item, expectedDispatchId, afterMutation = false) {
        const actualDispatchId = String(record?.leitstelle_building_id ?? '');
        if (actualDispatchId !== expectedDispatchId) {
            if (afterMutation) throw dispatchRecruitmentSafetyStop(`MissionChief reported that ${item.name}'s Dispatch Centre changed during a recruitment update. The bulk run was stopped immediately.`);
            throw dispatchRecruitmentSafeSkip('station is no longer assigned to its scanned Dispatch Centre');
        }
        if (String(record?.building_type ?? '') !== item.typeId) {
            if (afterMutation) throw dispatchRecruitmentSafetyStop(`MissionChief reported that ${item.name}'s building type changed during a recruitment update. The bulk run was stopped immediately.`);
            throw dispatchRecruitmentSafeSkip('station type changed after the scan');
        }
        return record;
    }

    async function verifyDispatchRecruitmentMutation(...args){return pilotInvokeFeature("administration","verifyDispatchRecruitmentMutation",{get dispatchRecruitmentAssertStationScope(){return typeof dispatchRecruitmentAssertStationScope==='undefined'?undefined:dispatchRecruitmentAssertStationScope},set dispatchRecruitmentAssertStationScope(value){dispatchRecruitmentAssertStationScope=value},get dispatchRecruitmentSafetyStop(){return typeof dispatchRecruitmentSafetyStop==='undefined'?undefined:dispatchRecruitmentSafetyStop},set dispatchRecruitmentSafetyStop(value){dispatchRecruitmentSafetyStop=value},get fetchDispatchRecruitmentBuilding(){return typeof fetchDispatchRecruitmentBuilding==='undefined'?undefined:fetchDispatchRecruitmentBuilding},set fetchDispatchRecruitmentBuilding(value){fetchDispatchRecruitmentBuilding=value},get runtimeDelay(){return typeof runtimeDelay==='undefined'?undefined:runtimeDelay},set runtimeDelay(value){runtimeDelay=value}},args);}

    function dispatchRecruitmentBoolean(value) {
        return value === true || value === 1 || value === '1' || String(value).toLowerCase() === 'true';
    }

    function dispatchRecruitmentRecordPhase(record) {
        if (dispatchRecruitmentBoolean(record?.hiring_automatic)) return 'automatic';
        const phase = String(Math.max(0, Math.min(3, Number(record?.hiring_phase) || 0)));
        return DISPATCH_RECRUITMENT_HIRING_PHASE_OPTIONS.includes(phase) ? phase : '0';
    }

    function dispatchRecruitmentRecordMatches(record, plan) {
        return Number(record?.personal_count_target) === Number(plan.personnelDesired) && dispatchRecruitmentRecordPhase(record) === plan.hiringPhase;
    }

    // Issue #764: a scan may show every eligible station, but only exact plan mismatches are selected by default.
    function dispatchRecruitmentConfiguredPlan() {
        const hiringPhase = String(state.dispatchRecruitment.hiringPhase || '');
        const personnelText = String(state.dispatchRecruitment.personnelDesired ?? '').trim();
        if (!DISPATCH_RECRUITMENT_HIRING_PHASE_OPTIONS.includes(hiringPhase)) return null;
        if (!/^\d+$/u.test(personnelText) || Number(personnelText) > DISPATCH_RECRUITMENT_PERSONNEL_MAX) return null;
        return { hiringPhase, personnelDesired: Number(personnelText) };
    }

    function dispatchRecruitmentScanItemMatchesPlan(item, plan) {
        return Boolean(plan)
            && String(item?.currentPhase || '') === plan.hiringPhase
            && Number(item?.currentDesired) === plan.personnelDesired;
    }

    function dispatchRecruitmentDefaultSelectedBuildingIds(queue, plan) {
        if (!plan) return new Set();
        return new Set(Array.from(queue || [])
            .filter(item => !dispatchRecruitmentScanItemMatchesPlan(item, plan))
            .map(item => item.buildingId));
    }

    function dispatchRecruitmentNativeHireAction(doc, buildingId, token) {
        const expectedPath = `/buildings/${buildingId}/hire_do/${token}`;
        for (const anchor of Array.from(doc?.querySelectorAll?.('a[href]') || [])) {
            try {
                const url = new URL(anchor.getAttribute('href'), document.baseURI || pageWindow.location.href);
                if (url.origin === pageWindow.location.origin && url.pathname === expectedPath && !url.search && !url.hash) return url.href;
            } catch (err) {}
        }
        return '';
    }

    function prepareDispatchRecruitmentPersonnelSubmission(doc, item, personnelDesired) {
        const expectedPath = `/buildings/${item.buildingId}`;
        const forms = Array.from(doc?.querySelectorAll?.('form[action]') || []);
        const matchingForms = forms.filter(candidate => {
            try {
                const action = new URL(candidate.getAttribute('action'), document.baseURI || pageWindow.location.href);
                const keys = Array.from(action.searchParams.keys());
                const supportedQuery = !keys.length || (keys.length === 1 && keys[0] === 'personal_count_target_only' && action.searchParams.get('personal_count_target_only') === '1');
                const targets = Array.from(candidate.getElementsByTagName('input')).filter(control => control.name === 'building[personal_count_target]');
                return action.origin === pageWindow.location.origin && action.pathname === expectedPath && !action.hash && supportedQuery && targets.length === 1;
            } catch (err) { return false; }
        });
        if (matchingForms.length !== 1) throw dispatchRecruitmentSafeSkip(matchingForms.length ? 'native Personnel (Desired) form is ambiguous' : 'native Personnel (Desired) form is unavailable');
        const form = matchingForms[0];
        if (String(form.getAttribute('method') || '').toLowerCase() !== 'post') throw dispatchRecruitmentSafeSkip('native Personnel (Desired) form method changed unexpectedly');
        const declaredBuildingId = String(form.getAttribute('building_id') || '');
        if (declaredBuildingId && declaredBuildingId !== item.buildingId) throw dispatchRecruitmentSafeSkip('native Personnel (Desired) form belongs to another station');
        const input = form.querySelector('input[name="building[personal_count_target]"]');
        const embeddedToken = String(form.querySelector('input[name="authenticity_token"]')?.value || '').trim();
        const pageToken = String(Array.from(document.getElementsByTagName('meta')).find(meta => meta.getAttribute('name') === 'csrf-token')?.getAttribute('content') || '').trim();
        const token = embeddedToken || pageToken;
        const methodOverride = String(form.querySelector('input[name="_method"]')?.value || '').toLowerCase();
        const submit = form.querySelector('input[type="submit"][name], button[type="submit"][name]');
        const unexpectedBuildingFields = Array.from(form.elements || [])
            .filter(control => !control.disabled && /^building\[/u.test(String(control.name || '')) && control.name !== 'building[personal_count_target]')
            .map(control => String(control.name));
        if (unexpectedBuildingFields.length) throw dispatchRecruitmentSafetyStop('the native Personnel (Desired) form exposed additional building fields. No request was sent.');
        if (!input || input.disabled || input.type !== 'number') throw dispatchRecruitmentSafeSkip('native Personnel (Desired) number input is unavailable');
        if (!token || !['put', 'patch'].includes(methodOverride)) throw dispatchRecruitmentSafeSkip('native Personnel (Desired) authenticity or update-method guard is unavailable');
        if (submit?.name !== 'commit') throw dispatchRecruitmentSafeSkip('native Personnel (Desired) Save action is unavailable');
        const action = new URL(form.getAttribute('action'), document.baseURI || pageWindow.location.href);
        if (!action.searchParams.has('personal_count_target_only')) action.searchParams.set('personal_count_target_only', '1');
        const params = new URLSearchParams();
        const utf8 = form.querySelector('input[type="hidden"][name="utf8"]');
        if (utf8 && !utf8.disabled) params.set('utf8', utf8.value || '✓');
        params.set('authenticity_token', token);
        params.set('_method', methodOverride);
        params.set('building[personal_count_target]', String(personnelDesired));
        params.set('commit', submit.value || dispatchRecruitmentText(submit.textContent));
        dispatchRecruitmentGuardMutation(action.href, params.toString());
        return {
            action: action.href,
            body: params.toString(),
            headers: {
                Accept: 'text/html,application/xhtml+xml',
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                'X-CSRF-Token': token,
                'X-Requested-With': 'XMLHttpRequest'
            }
        };
    }

