    function dispatchRecruitmentVisibleQueue() {
        return dispatchRecruitmentRuntime.queue.filter(item => dispatchRecruitmentRuntime.selectedTypeIds.has(item.typeId));
    }

    function dispatchRecruitmentPlannedQueue() {
        return dispatchRecruitmentVisibleQueue().filter(item => dispatchRecruitmentRuntime.selectedBuildingIds.has(item.buildingId));
    }

    function dispatchRecruitmentSelectVisible(selected) {
        if (dispatchRecruitmentRuntime.running || dispatchRecruitmentRuntime.scanPromise || stationIconCopierRuntime.running || stationIconCopierRuntime.preparing || stationIconCopierRuntime.scanPromise || stationIconCopierRuntime.catalogPromise || expansionPlannerRuntime.running || expansionPlannerRuntime.preparing || expansionPlannerRuntime.scanPromise || expansionPlannerRuntime.catalogPromise) return;
        for (const item of dispatchRecruitmentVisibleQueue()) {
            if (selected) dispatchRecruitmentRuntime.selectedBuildingIds.add(item.buildingId);
            else dispatchRecruitmentRuntime.selectedBuildingIds.delete(item.buildingId);
        }
        resetDispatchRecruitmentResults();
        renderDispatchRecruitmentPanel();
    }

    function renderDispatchRecruitmentPanel() {
        const panel = commandExperienceElement(SCRIPT.panelId);
        const host = panel?.querySelector?.('[data-dispatch-recruitment]');
        if (!host) return;
        const runtimeState = dispatchRecruitmentRuntime;
        const locked = runtimeState.running || Boolean(runtimeState.scanPromise) || Boolean(runtimeState.catalogPromise) || stationIconCopierRuntime.running || stationIconCopierRuntime.preparing || Boolean(stationIconCopierRuntime.scanPromise) || Boolean(stationIconCopierRuntime.catalogPromise) || expansionPlannerRuntime.running || expansionPlannerRuntime.preparing || Boolean(expansionPlannerRuntime.scanPromise) || Boolean(expansionPlannerRuntime.catalogPromise);
        const planLocked = runtimeState.running;
        const dispatchSelect = panel.querySelector('[data-setting="dispatch-recruitment-centre"]');
        const dispatchOptions = runtimeState.dispatches.length
            ? `<option value="${DISPATCH_RECRUITMENT_ALL_CENTRES}">ALL DISPATCH CENTRES</option>${runtimeState.dispatches.map(item => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.name)}</option>`).join('')}`
            : `<option value="">${runtimeState.catalogPromise ? 'Loading Dispatch Centres…' : 'Load Dispatch Centres first'}</option>`;
        setInnerHtmlIfChanged(dispatchSelect, dispatchOptions);
        if (dispatchSelect) {
            updateUiSetProperty(dispatchSelect, 'value', state.dispatchRecruitment.dispatchId);
            updateUiSetProperty(dispatchSelect, 'disabled', locked || !runtimeState.dispatches.length);
        }
        const buildingTypeSelect = Array.from(panel.getElementsByTagName('select')).find(control => control.dataset.setting === 'dispatch-recruitment-building-type');
        const catalogTypeEntries = Object.entries(runtimeState.typeLabels).sort((left, right) => left[1].localeCompare(right[1], undefined, { sensitivity: 'base' }));
        const buildingTypeOptions = runtimeState.dispatches.length
            ? `<option value="${DISPATCH_RECRUITMENT_ALL_TYPES}">ALL BUILDING TYPES</option>${catalogTypeEntries.map(([typeId, label]) => `<option value="${escapeHtml(typeId)}">${escapeHtml(label)}</option>`).join('')}`
            : `<option value="${DISPATCH_RECRUITMENT_ALL_TYPES}">${runtimeState.catalogPromise ? 'Loading Building Types…' : 'Load Dispatch Centres first'}</option>`;
        setInnerHtmlIfChanged(buildingTypeSelect, buildingTypeOptions);
        if (buildingTypeSelect) {
            updateUiSetProperty(buildingTypeSelect, 'value', state.dispatchRecruitment.buildingTypeId);
            updateUiSetProperty(buildingTypeSelect, 'disabled', locked || !runtimeState.dispatches.length);
        }
        panel.querySelectorAll('[data-setting^="dispatch-recruitment-"]').forEach(control => {
            if (control === dispatchSelect || control === buildingTypeSelect || ['dispatch-recruitment-type', 'dispatch-recruitment-station'].includes(control.dataset.setting)) return;
            updateUiSetProperty(control, 'disabled', planLocked);
        });
        const allCentres = state.dispatchRecruitment.dispatchId === DISPATCH_RECRUITMENT_ALL_CENTRES;
        const summary = runtimeState.summary || { totalRows: 0, eligible: 0, unassigned: 0, outsideDispatch: 0, outsideType: 0, unavailable: 0, typeCounts: {}, dispatchCounts: {}, unassignedNames: [], outsideDispatchNames: [], outsideTypeNames: [], unavailableNames: [] };
        const visibleQueue = dispatchRecruitmentVisibleQueue();
        const plannedQueue = dispatchRecruitmentPlannedQueue();
        const status = runtimeState.running ? (runtimeState.stopRequested ? 'STOPPING' : 'RUNNING') : runtimeState.scanPromise ? 'SCANNING' : runtimeState.catalogPromise ? 'LOADING' : runtimeState.scannedAt ? (runtimeState.processed ? 'COMPLETE' : 'READY') : 'IDLE';
        const typeEntries = Object.entries(summary.typeCounts || {}).sort((left, right) => {
            const leftLabel = runtimeState.typeLabels[left[0]] || `Building type ${left[0]}`;
            const rightLabel = runtimeState.typeLabels[right[0]] || `Building type ${right[0]}`;
            return leftLabel.localeCompare(rightLabel, undefined, { sensitivity: 'base' });
        });
        const filters = typeEntries.length ? `<div class="mcms-recruitment-filters">${typeEntries.map(([typeId, count]) => {
            const label = runtimeState.typeLabels[typeId] || `Building type ${typeId}`;
            return `<label class="mcms-recruitment-type"><input type="checkbox" data-setting="dispatch-recruitment-type" value="${escapeHtml(typeId)}" ${runtimeState.selectedTypeIds.has(typeId) ? 'checked' : ''} ${locked ? 'disabled' : ''}><span>${escapeHtml(label)}</span><b>${count}</b></label>`;
        }).join('')}</div>` : `<div class="mcms-empty-state">Scan ${allCentres ? 'ALL DISPATCH CENTRES' : 'a Dispatch Centre'} to load current native station types.</div>`;
        const emptyStationMessage = runtimeState.scannedAt && !summary.eligible
            ? `No editable stations are assigned within this scope. ${summary.unassigned} unassigned, ${summary.outsideDispatch} assigned outside the scope and ${summary.unavailable} unavailable row${summary.unavailable === 1 ? '' : 's'} were excluded.`
            : runtimeState.scannedAt ? 'No stations match the active type filters.' : `Load and scan ${allCentres ? 'ALL DISPATCH CENTRES' : 'a Dispatch Centre'} to preview editable stations.`;
        const stationRows = visibleQueue.length ? visibleQueue.map(item => {
            const selected = runtimeState.selectedBuildingIds.has(item.buildingId);
            const current = runtimeState.currentBuildingId === item.buildingId;
            const matchesPlan = runtimeState.matchingBuildingIds.has(item.buildingId);
            const outcome = item.outcome === 'updated' ? 'UPDATED' : item.outcome === 'partial' ? 'PARTIAL' : item.outcome === 'unchanged' ? 'NO CHANGE' : item.outcome === 'skipped' ? 'SKIPPED' : item.outcome === 'error' ? 'ERROR' : selected ? 'SELECTED' : matchesPlan ? 'MATCHES' : 'EXCLUDED';
            const detail = item.outcomeDetail ? ` · ${item.outcomeDetail}` : '';
            const centre = allCentres ? `${item.dispatchName || `Dispatch Centre ${item.dispatchId}`} · ` : '';
            return `<label class="mcms-recruitment-station ${current ? 'mcms-current' : ''}" data-outcome="${escapeHtml(item.outcome)}"><input type="checkbox" data-setting="dispatch-recruitment-station" value="${escapeHtml(item.buildingId)}" ${selected ? 'checked' : ''} ${locked ? 'disabled' : ''}><span><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(centre)}${escapeHtml(item.typeLabel)} · Hiring ${escapeHtml(dispatchRecruitmentPhaseLabel(item.currentPhase))} · Desired ${item.currentDesired} · Staff ${escapeHtml(item.currentStaff)}${escapeHtml(detail)}</small></span><b>${outcome}</b></label>`;
        }).join('') : `<div class="mcms-empty-state">${escapeHtml(emptyStationMessage)}</div>`;
        const assignedLabel = allCentres ? 'Assigned' : 'Assigned here';
        const scopeStat = allCentres
            ? `<div class="mcms-sweep-stat"><b>${Object.keys(summary.dispatchCounts || {}).length}</b><span>Centres</span></div>`
            : `<div class="mcms-sweep-stat"><b>${summary.outsideDispatch}</b><span>Other centres</span></div>`;
        const runStats = runtimeState.running || runtimeState.processed
            ? `<div class="mcms-sweep-stat"><b>${runtimeState.processed}/${Math.min(plannedQueue.length || runtimeState.processed, DISPATCH_RECRUITMENT_APPLY_LIMIT)}</b><span>Processed</span></div><div class="mcms-sweep-stat"><b>${runtimeState.updated}</b><span>Updated</span></div><div class="mcms-sweep-stat"><b>${runtimeState.partial}</b><span>Partial</span></div><div class="mcms-sweep-stat"><b>${runtimeState.unchanged}</b><span>No change</span></div><div class="mcms-sweep-stat"><b>${runtimeState.skipped + runtimeState.errors}</b><span>Issues</span></div>`
            : `<div class="mcms-sweep-stat"><b>${summary.eligible}</b><span>${assignedLabel}</span></div><div class="mcms-sweep-stat"><b>${plannedQueue.length}</b><span>Selected</span></div>${scopeStat}<div class="mcms-sweep-stat"><b>${summary.unavailable}</b><span title="Unavailable">Blocked</span></div>`;
        const activity = runtimeState.currentItem ? `<div class="mcms-status"><strong>Current:</strong> ${escapeHtml(runtimeState.currentItem)}</div>` : '';
        const outsideDispatchLabel = allCentres ? 'with assignments outside the loaded Dispatch Centre catalogue' : 'assigned to other Dispatch Centres';
        const unassigned = summary.unassignedNames?.length ? `<details class="mcms-recruitment-findings"><summary>${summary.unassigned} unassigned row${summary.unassigned === 1 ? '' : 's'} — excluded from all recruitment changes</summary>${summary.unassignedNames.map(name => `<div>${escapeHtml(name)}</div>`).join('')}${summary.unassigned > summary.unassignedNames.length ? `<div>+ ${summary.unassigned - summary.unassignedNames.length} more</div>` : ''}</details>` : '';
        const outsideDispatch = summary.outsideDispatchNames?.length ? `<details class="mcms-recruitment-findings"><summary>${summary.outsideDispatch} row${summary.outsideDispatch === 1 ? '' : 's'} ${outsideDispatchLabel}</summary>${summary.outsideDispatchNames.map(name => `<div>${escapeHtml(name)}</div>`).join('')}${summary.outsideDispatch > summary.outsideDispatchNames.length ? `<div>+ ${summary.outsideDispatch - summary.outsideDispatchNames.length} more</div>` : ''}</details>` : '';
        const unavailable = summary.unavailableNames?.length ? `<details class="mcms-recruitment-findings"><summary>${summary.unavailable} unavailable row${summary.unavailable === 1 ? '' : 's'}</summary>${summary.unavailableNames.map(name => `<div>${escapeHtml(name)}</div>`).join('')}${summary.unavailable > summary.unavailableNames.length ? `<div>+ ${summary.unavailable - summary.unavailableNames.length} more</div>` : ''}</details>` : '';
        const logs = runtimeState.log.length ? runtimeState.log.map(entry => {
            const stamp = new Date(entry.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' });
            return `<div data-level="${escapeHtml(entry.level)}">${escapeHtml(stamp)} · ${escapeHtml(entry.message)}</div>`;
        }).join('') : '<div>No recruitment activity yet.</div>';
        const html = `<div class="mcms-sweep-card mcms-recruitment-card"><div class="mcms-sweep-head"><span>Dispatch Recruitment</span><span class="mcms-sweep-state ${runtimeState.running ? 'mcms-running' : ''}">${status}</span></div><div class="mcms-sweep-stats">${runStats}</div>${activity}<div class="mcms-recruitment-filter-head"><span>Station types</span><b>${plannedQueue.length} selected / ${visibleQueue.length} visible</b></div>${filters}<div class="mcms-recruitment-stations">${stationRows}</div>${unassigned}${outsideDispatch}${unavailable}<div class="mcms-sweep-log">${logs}</div></div>`;
        setInnerHtmlIfChanged(host, html);
        const load = panel.querySelector('[data-action="load-dispatch-recruitment"]');
        const scan = panel.querySelector('[data-action="scan-dispatch-recruitment"]');
        const apply = panel.querySelector('[data-action="apply-dispatch-recruitment"]');
        const stop = panel.querySelector('[data-action="stop-dispatch-recruitment"]');
        const selectAll = panel.querySelector('[data-action="select-all-dispatch-recruitment"]');
        const clear = panel.querySelector('[data-action="clear-dispatch-recruitment"]');
        if (load) load.disabled = locked;
        const validTypeScope = state.dispatchRecruitment.buildingTypeId === DISPATCH_RECRUITMENT_ALL_TYPES || Object.prototype.hasOwnProperty.call(runtimeState.typeLabels, state.dispatchRecruitment.buildingTypeId);
        if (scan) scan.disabled = locked || !runtimeState.dispatches.length || !validTypeScope;
        if (apply) apply.disabled = locked || !plannedQueue.length || runtimeState.scannedDispatchId !== state.dispatchRecruitment.dispatchId || runtimeState.scannedTypeId !== state.dispatchRecruitment.buildingTypeId;
        if (stop) stop.disabled = !runtimeState.running;
        if (selectAll) selectAll.disabled = locked || !visibleQueue.length;
        if (clear) clear.disabled = locked || !visibleQueue.length;
    
pilot.operations?.refresh();
}

    function readDispatchRecruitmentPlan() {
        const panel = commandExperienceElement(SCRIPT.panelId);
        const phase = String(panel?.querySelector?.('[data-setting="dispatch-recruitment-hiring-phase"]')?.value ?? state.dispatchRecruitment.hiringPhase);
        const personnelText = String(panel?.querySelector?.('[data-setting="dispatch-recruitment-personnel"]')?.value ?? state.dispatchRecruitment.personnelDesired).trim();
        const delay = Number(panel?.querySelector?.('[data-setting="dispatch-recruitment-delay"]')?.value ?? state.dispatchRecruitment.delayMs);
        const buildingTypeId = String(state.dispatchRecruitment.buildingTypeId || DISPATCH_RECRUITMENT_ALL_TYPES);
        if (buildingTypeId !== DISPATCH_RECRUITMENT_ALL_TYPES && !Object.prototype.hasOwnProperty.call(dispatchRecruitmentRuntime.typeLabels, buildingTypeId)) throw new Error('Choose a building type loaded from MissionChief.');
        if (!DISPATCH_RECRUITMENT_HIRING_PHASE_OPTIONS.includes(phase)) throw new Error('Choose a valid Hiring Phase.');
        if (!/^\d+$/u.test(personnelText) || Number(personnelText) > DISPATCH_RECRUITMENT_PERSONNEL_MAX) throw new Error(`Personnel (Desired) must be a whole number from 0 to ${DISPATCH_RECRUITMENT_PERSONNEL_MAX}.`);
        state.dispatchRecruitment.hiringPhase = phase;
        state.dispatchRecruitment.personnelDesired = String(Number(personnelText));
        state.dispatchRecruitment.delayMs = DISPATCH_RECRUITMENT_DELAY_OPTIONS.includes(delay) ? delay : 1500;
        saveState();
        return {
            dispatchId: String(state.dispatchRecruitment.dispatchId),
            buildingTypeId,
            hiringPhase: phase,
            personnelDesired: Number(personnelText),
            delayMs: state.dispatchRecruitment.delayMs
        };
    }

