    function validateFinancialPolicy(payload) {
        if (!payload || Number(payload.schema) !== 2 || typeof payload.risk !== 'object' || typeof payload.scan !== 'object') return null;
        const number = (value, minimum, maximum, fallback) => clamp(Number(value), minimum, maximum, fallback);
        return {
            schema: 2,
            version: String(payload.version || 'remote').slice(0, 80),
            risk: {
                classificationCritical: number(payload.risk.classificationCritical, 40, 95, BUILTIN_FINANCIAL_POLICY.risk.classificationCritical),
                classificationWarning: number(payload.risk.classificationWarning, 50, 100, BUILTIN_FINANCIAL_POLICY.risk.classificationWarning),
                capitalIncomeRatio: number(payload.risk.capitalIncomeRatio, 50, 500, BUILTIN_FINANCIAL_POLICY.risk.capitalIncomeRatio),
                allianceConcentration: number(payload.risk.allianceConcentration, 40, 100, BUILTIN_FINANCIAL_POLICY.risk.allianceConcentration),
                categoryConcentration: number(payload.risk.categoryConcentration, 40, 100, BUILTIN_FINANCIAL_POLICY.risk.categoryConcentration),
                volatilityWarning: number(payload.risk.volatilityWarning, 50, 500, BUILTIN_FINANCIAL_POLICY.risk.volatilityWarning),
                revenueContraction: number(payload.risk.revenueContraction, -90, -5, BUILTIN_FINANCIAL_POLICY.risk.revenueContraction),
                drawdownWarning: number(payload.risk.drawdownWarning, 5, 90, BUILTIN_FINANCIAL_POLICY.risk.drawdownWarning),
                runwayCriticalDays: number(payload.risk.runwayCriticalDays, 0.5, 30, BUILTIN_FINANCIAL_POLICY.risk.runwayCriticalDays)
            },
            scan: {
                pageCap: Math.round(number(payload.scan.pageCap, 100, FINANCE_DEEP_SCAN_HARD_PAGE_CAP, BUILTIN_FINANCIAL_POLICY.scan.pageCap)),
                batchSize: Math.round(number(payload.scan.batchSize, 1, FINANCE_DEEP_SCAN_HARD_BATCH_CAP, BUILTIN_FINANCIAL_POLICY.scan.batchSize)),
                retryAttempts: Math.round(number(payload.scan.retryAttempts, 1, 5, BUILTIN_FINANCIAL_POLICY.scan.retryAttempts)),
                checkpointPages: Math.round(number(payload.scan.checkpointPages, 20, 500, BUILTIN_FINANCIAL_POLICY.scan.checkpointPages))
            }
        };
    }

    function applyFinancialPolicyPayload(payload, { cache = false } = {}) {
        const policy = validateFinancialPolicy(payload);
        if (!policy) return false;
        activeFinancialPolicy = policy;
        activeFinancialPolicyVersion = policy.version;
        if (cache) gmSetValueSafe(SCRIPT.financePolicyCacheState, JSON.stringify({ fetchedAt: Date.now(), payload }));
        return true;
    }

    function loadCachedFinancialPolicy() {
        const raw = gmGetValueSafe(SCRIPT.financePolicyCacheState, '');
        let cache = null;
        try { cache = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (err) {}
        if (!cache?.payload || !applyFinancialPolicyPayload(cache.payload)) return 0;
        return Number(cache.fetchedAt) || 0;
    }

