    function mergeFinanceVaultStores(existingStore, importedStore) {
        const result = { schema: FINANCE_VAULT_SCHEMA, profiles: { ...(existingStore?.profiles || {}) } };
        for (const [rawKey, rawVault] of Object.entries(importedStore?.profiles || {}).slice(0, 100)) {
            if (!rawVault || typeof rawVault !== 'object') continue;
            const player = {
                id: rawVault?.player?.id === undefined || rawVault?.player?.id === null || rawVault?.player?.id === '' ? null : String(rawVault.player.id).slice(0, 64),
                name: financeNormaliseText(rawVault?.player?.name).slice(0, 120)
            };
            const key = player.id || player.name ? financePlayerProfileKey(player) : String(rawKey || '').slice(0, 180);
            if (!key) continue;
            const imported = normaliseFinanceVault(rawVault, player, financeVaultCredential().deviceId);
            const current = normaliseFinanceVault(result.profiles[key], player, financeVaultCredential().deviceId);
            const transactions = new Map(current.transactions.map(entry => [entry.fingerprint, entry]));
            for (const entry of imported.transactions) transactions.set(entry.fingerprint, entry);
            const checkpoints = new Map(current.balanceCheckpoints.map(item => [`${item.timestamp}|${item.balance}`, item]));
            for (const item of imported.balanceCheckpoints) checkpoints.set(`${item.timestamp}|${item.balance}`, item);
            current.transactions = Array.from(transactions.values()).sort((a, b) => a.timestamp - b.timestamp || a.fingerprint.localeCompare(b.fingerprint));
            current.balanceCheckpoints = Array.from(checkpoints.values()).sort((a, b) => a.timestamp - b.timestamp).slice(-FINANCE_VAULT_MAX_CHECKPOINTS);
            const starts = [current.coverageStartMs, imported.coverageStartMs].filter(Number.isFinite);
            const ends = [current.coverageEndMs, imported.coverageEndMs].filter(Number.isFinite);
            current.coverageStartMs = starts.length ? Math.min(...starts) : null;
            current.coverageEndMs = ends.length ? Math.max(...ends) : null;
            current.lastFullScanAt = Math.max(current.lastFullScanAt, imported.lastFullScanAt);
            current.lastIncrementalScanAt = Math.max(current.lastIncrementalScanAt, imported.lastIncrementalScanAt);
            current.lastDeepScanAt = Math.max(current.lastDeepScanAt, imported.lastDeepScanAt);
            current.sourceLastPage = Math.max(current.sourceLastPage, imported.sourceLastPage);
            current.deepScanCursorPage = Math.max(current.deepScanCursorPage, imported.deepScanCursorPage);
            current.deepScanTotalPages = Math.max(current.deepScanTotalPages, imported.deepScanTotalPages);
            if (imported.deepScanInProgress && imported.deepScanCursorPage >= current.deepScanCursorPage) current.deepScanAnchor = imported.deepScanAnchor;
            current.deepScanInProgress = Boolean(current.deepScanInProgress || imported.deepScanInProgress);
            current.archiveComplete = Boolean(current.archiveComplete || imported.archiveComplete);
            current.archiveTruncated = Boolean(current.archiveTruncated || imported.archiveTruncated);
            if (current.archiveComplete) current.deepScanInProgress = false;
            current.droppedTransactions += imported.droppedTransactions;
            result.profiles[key] = current;
        }
        return result;
    }

