    async function scanFinancialArchive(...args){return pilotInvokeFeature("finance","scanFinancialArchive",{},args);}

    function classifyFinancialTransaction(transaction) {
        const description = financeNormaliseText(transaction?.description);
        const amount = Number(transaction?.amount) || 0;
        const direction = amount > 0 ? 'income' : 'spending';
        for (const rule of activeFinancialRules) {
            if (rule.direction !== direction) continue;
            if (!ruleMatchesFinancialDescription(rule, description)) continue;
            return {
                key: rule.key,
                label: rule.label,
                kind: direction,
                missionType: rule.missionType || '',
                accountingGroup: rule.accountingGroup,
                confidence: clamp(rule.confidence, 0, 1, 0.5),
                ruleId: rule.id,
                source: rule.source || 'built-in'
            };
        }
        const fallback = activeFinancialFallbacks[direction] || BUILTIN_FINANCIAL_FALLBACKS[direction];
        return {
            key: fallback.key,
            label: fallback.label,
            kind: direction,
            missionType: fallback.missionType || '',
            accountingGroup: fallback.accountingGroup,
            confidence: clamp(fallback.confidence, 0, 1, 0.25),
            ruleId: fallback.id || `fallback-${direction}`,
            source: 'fallback'
        };
    }

    function buildFinancialBuckets(transactions, startMs, endMs) {
        const duration = Math.max(1, endMs - startMs);
        const useHourly = duration <= 48 * 60 * 60 * 1000;
        const targetBuckets = useHourly ? 12 : duration <= 31 * 86400000 ? 31 : 24;
        const unitMs = useHourly ? 60 * 60 * 1000 : 24 * 60 * 60 * 1000;
        const bucketMs = Math.max(unitMs, Math.ceil(duration / targetBuckets / unitMs) * unitMs);
        const count = Math.max(1, Math.min(targetBuckets, Math.ceil(duration / bucketMs)));
        const buckets = Array.from({ length: count }, (_, index) => ({
            start: startMs + index * bucketMs,
            end: Math.min(endMs, startMs + (index + 1) * bucketMs),
            income: 0,
            operatingIncome: 0,
            otherIncome: 0,
            operatingExpense: 0,
            capitalInvestment: 0,
            spending: 0,
            operatingResult: 0,
            net: 0,
            label: ''
        }));
        for (const transaction of transactions) {
            const index = Math.min(count - 1, Math.max(0, Math.floor((transaction.timestamp - startMs) / bucketMs)));
            if (!buckets[index] || transaction.timestamp < startMs || transaction.timestamp >= endMs) continue;
            const category = transaction.classification || classifyFinancialTransaction(transaction);
            const amount = Number(transaction.amount) || 0;
            if (amount > 0) {
                buckets[index].income += amount;
                if (category.accountingGroup === 'operatingIncome') buckets[index].operatingIncome += amount;
                else buckets[index].otherIncome += amount;
            } else {
                const absolute = Math.abs(amount);
                buckets[index].spending += absolute;
                if (category.accountingGroup === 'capitalInvestment') buckets[index].capitalInvestment += absolute;
                else buckets[index].operatingExpense += absolute;
            }
            buckets[index].operatingResult = buckets[index].operatingIncome + buckets[index].otherIncome - buckets[index].operatingExpense;
            buckets[index].net += amount;
        }
        for (const bucket of buckets) {
            const date = new Date(bucket.start);
            bucket.label = useHourly
                ? date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                : date.toLocaleDateString('en-GB', duration > 180 * 86400000 ? { month: 'short', year: '2-digit' } : { day: 'numeric', month: 'short' });
        }
        return buckets;
    }

    function calculateActiveHours(transactions) {
        const activeQuarterHours = new Set();
        for (const entry of transactions) {
            if (!Number.isFinite(Number(entry.timestamp))) continue;
            activeQuarterHours.add(Math.floor(Number(entry.timestamp) / (15 * 60 * 1000)));
        }
        return Math.max(0.25, activeQuarterHours.size * 0.25);
    }

    function medianNumber(values) {
        const sorted = values.filter(Number.isFinite).sort((a, b) => a - b);
        if (!sorted.length) return 0;
        const middle = Math.floor(sorted.length / 2);
        return sorted.length % 2 ? sorted[middle] : Math.round((sorted[middle - 1] + sorted[middle]) / 2);
    }

    function standardDeviation(values) {
        const finite = values.filter(Number.isFinite);
        if (finite.length < 2) return 0;
        const average = finite.reduce((sum, value) => sum + value, 0) / finite.length;
        return Math.sqrt(finite.reduce((sum, value) => sum + Math.pow(value - average, 2), 0) / finite.length);
    }

    function summariseFinancialTransactions(transactions, period) {
        const incomeCategoryMap = new Map();
        const spendingCategoryMap = new Map();
        const operatingExpenseCategoryMap = new Map();
        const capitalCategoryMap = new Map();
        const topPayouts = [];
        const missionPayoutValues = [];
        const unclassifiedEntries = [];
        let income = 0;
        let spending = 0;
        let operatingIncome = 0;
        let otherIncome = 0;
        let operatingExpense = 0;
        let capitalInvestment = 0;
        let incomeCount = 0;
        let spendingCount = 0;
        let missionCount = 0;
        let missionIncome = 0;
        let allianceIncome = 0;
        let personalIncome = 0;
        let transportIncome = 0;
        let largestReward = 0;
        let smallestReward = Infinity;
        let largestSpend = 0;
        let classificationWeight = 0;
        let classificationWeightedScore = 0;
        let unclassifiedAmount = 0;
        let unclassifiedCount = 0;
        let hasMissionPayout = false;
        const addCategory = (map, category, amount) => {
            const existing = map.get(category.key) || { key: category.key, label: category.label, accountingGroup: category.accountingGroup, total: 0, count: 0 };
            existing.total += Math.abs(amount);
            existing.count += 1;
            map.set(category.key, existing);
        };
        const addTopPayout = entry => {
            topPayouts.push(entry);
            topPayouts.sort((a, b) => b.amount - a.amount);
            if (topPayouts.length > 8) topPayouts.length = 8;
        };
        const classifiedTransactions = [];
        for (const sourceEntry of transactions) {
            const amount = Number(sourceEntry.amount) || 0;
            if (!amount) continue;
            const category = classifyFinancialTransaction(sourceEntry);
            const entry = { ...sourceEntry, classification: category };
            classifiedTransactions.push(entry);
            const weight = Math.max(1, Math.abs(amount));
            classificationWeight += weight;
            classificationWeightedScore += weight * category.confidence;
            const isUnclassified = category.ruleId.startsWith('fallback') || category.key.startsWith('unclassified');
            if (isUnclassified) {
                unclassifiedAmount += Math.abs(amount);
                unclassifiedCount += 1;
                if (unclassifiedEntries.length < 20) unclassifiedEntries.push(entry);
            }
            if (amount > 0) {
                income += amount;
                incomeCount += 1;
                addCategory(incomeCategoryMap, category, amount);
                if (category.accountingGroup === 'operatingIncome') operatingIncome += amount;
                else otherIncome += amount;
                if (category.missionType) {
                    missionCount += 1;
                    missionIncome += amount;
                    hasMissionPayout = true;
                    missionPayoutValues.push(amount);
                    largestReward = Math.max(largestReward, amount);
                    smallestReward = Math.min(smallestReward, amount);
                    addTopPayout(entry);
                }
                if (category.missionType === 'alliance') allianceIncome += amount;
                if (category.missionType === 'personal') personalIncome += amount;
                if (category.missionType === 'transport') transportIncome += amount;
            } else {
                const absolute = Math.abs(amount);
                spending += absolute;
                spendingCount += 1;
                largestSpend = Math.max(largestSpend, absolute);
                addCategory(spendingCategoryMap, category, amount);
                if (category.accountingGroup === 'capitalInvestment') {
                    capitalInvestment += absolute;
                    addCategory(capitalCategoryMap, category, amount);
                } else {
                    operatingExpense += absolute;
                    addCategory(operatingExpenseCategoryMap, category, amount);
                }
            }
        }
        if (!hasMissionPayout) {
            topPayouts.length = 0;
            largestReward = 0;
            smallestReward = Infinity;
            for (const entry of classifiedTransactions) {
                if (entry.amount <= 0) continue;
                largestReward = Math.max(largestReward, entry.amount);
                smallestReward = Math.min(smallestReward, entry.amount);
                addTopPayout(entry);
            }
        }
        const net = income - spending;
        const operatingResult = operatingIncome + otherIncome - operatingExpense;
        const calendarHours = Math.max(1 / 60, period.durationMs / (60 * 60 * 1000));
        const calendarDays = Math.max(1 / 24, calendarHours / 24);
        const activeHours = calculateActiveHours(classifiedTransactions);
        const buckets = buildFinancialBuckets(classifiedTransactions, period.startMs, period.endMs);
        const classificationConfidence = classificationWeight ? Math.round((classificationWeightedScore / classificationWeight) * 1000) / 10 : 100;
        const operatingMarginPercent = income ? Math.round((operatingResult / income) * 1000) / 10 : operatingExpense ? -100 : 0;
        const capitalInvestmentRatioPercent = income ? Math.round((capitalInvestment / income) * 1000) / 10 : capitalInvestment ? 100 : 0;
        const topIncomeCategory = Array.from(incomeCategoryMap.values()).sort((a, b) => b.total - a.total)[0] || null;
        const incomeConcentrationPercent = income && topIncomeCategory ? Math.round((topIncomeCategory.total / income) * 1000) / 10 : 0;
        const bucketIncomeValues = buckets.map(bucket => bucket.income);
        const incomeVolatilityPercent = bucketIncomeValues.length && income
            ? Math.round((standardDeviation(bucketIncomeValues) / Math.max(1, bucketIncomeValues.reduce((sum, value) => sum + value, 0) / bucketIncomeValues.length)) * 1000) / 10
            : 0;
        return {
            transactions: classifiedTransactions,
            incomeCategories: Array.from(incomeCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            spendingCategories: Array.from(spendingCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            operatingExpenseCategories: Array.from(operatingExpenseCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            capitalCategories: Array.from(capitalCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            income,
            spending,
            operatingIncome,
            otherIncome,
            operatingExpense,
            capitalInvestment,
            operatingResult,
            net,
            incomeCount,
            spendingCount,
            activityCount: incomeCount + spendingCount,
            missionCount,
            missionIncome,
            averageIncome: incomeCount ? Math.round(income / incomeCount) : 0,
            averageSpend: spendingCount ? Math.round(spending / spendingCount) : 0,
            averageMissionReward: missionCount ? Math.round(missionIncome / missionCount) : 0,
            medianMissionReward: medianNumber(missionPayoutValues),
            largestReward,
            smallestReward: Number.isFinite(smallestReward) ? smallestReward : 0,
            largestSpend,
            allianceIncome,
            personalIncome,
            transportIncome,
            allianceIncomePercent: income ? Math.round((allianceIncome / income) * 1000) / 10 : 0,
            personalIncomePercent: income ? Math.round((personalIncome / income) * 1000) / 10 : 0,
            incomePerHour: Math.round(income / calendarHours),
            activeIncomePerHour: Math.round(income / activeHours),
            activeHours: Math.round(activeHours * 100) / 100,
            calendarHours: Math.round(calendarHours * 100) / 100,
            calendarDays: Math.round(calendarDays * 1000) / 1000,
            classificationConfidence,
            unclassifiedAmount,
            unclassifiedCount,
            unclassifiedEntries,
            operatingMarginPercent,
            capitalInvestmentRatioPercent,
            incomeConcentrationPercent,
            incomeVolatilityPercent,
            topIncomeCategory,
            topPayouts,
            buckets
        };
    }

    function financialOverviewDayIsAuthoritative(dayStartMs, period) {
        const dayStart = Number(dayStartMs);
        const dayEnd = addLocalDays(dayStart, 1);
        if (!Number.isFinite(dayStart) || period.startMs > dayStart) return false;
        const todayStart = localDayStart();
        if (dayStart === todayStart) return period.endMs >= Date.now() - 10 * 60 * 1000;
        return period.endMs >= dayEnd;
    }

    function reconcileFinancialOverview(summary, transactions, period, overview) {
        if (summary?.overviewAudit) return summary;
        const base = { ...summary, buckets: summary.buckets.map(bucket => ({ ...bucket })) };
        const unavailable = !overview?.available || !Array.isArray(overview.rows) || !overview.rows.length;
        const emptyAudit = {
            available: !unavailable,
            status: unavailable ? 'unavailable' : 'not-applicable',
            label: unavailable ? 'Credits overview unavailable; detailed ledger totals retained' : 'No complete overview day falls inside this period',
            rowsUsed: 0,
            rowsCompared: 0,
            pageCount: Number(overview?.pageCount) || 0,
            lastPage: Number(overview?.lastPage) || 0,
            coverageReached: Boolean(overview?.coverageReached),
            malformedRowCount: Number(overview?.malformedRowCount) || 0,
            duplicateDateCount: Number(overview?.duplicateDateCount) || 0,
            ledgerIncome: summary.income,
            ledgerSpending: summary.spending,
            ledgerNet: summary.net,
            overviewIncome: 0,
            overviewSpending: 0,
            overviewNet: 0,
            incomeVariance: 0,
            spendingVariance: 0,
            netVariance: 0,
            unresolvedVariance: 0,
            days: [],
            error: String(overview?.error || '')
        };
        if (unavailable) return { ...base, overviewAudit: emptyAudit };
        const ledgerDays = new Map();
        for (const entry of transactions) {
            const timestamp = Number(entry?.timestamp);
            if (!Number.isFinite(timestamp) || timestamp < period.startMs || timestamp >= period.endMs) continue;
            const dateKey = localIsoDate(new Date(timestamp));
            const day = ledgerDays.get(dateKey) || { income: 0, spending: 0, net: 0 };
            const amount = Number(entry.amount) || 0;
            if (amount > 0) day.income += amount;
            else day.spending += amount;
            day.net += amount;
            ledgerDays.set(dateKey, day);
        }
        const auditDays = [];
        let coveredLedgerIncome = 0;
        let coveredLedgerSpending = 0;
        let coveredLedgerNet = 0;
        let overviewIncome = 0;
        let overviewSpending = 0;
        let overviewNet = 0;
        for (const row of overview.rows) {
            if (row.dayEndMs <= period.startMs || row.dayStartMs >= period.endMs) continue;
            if (!financialOverviewDayIsAuthoritative(row.dayStartMs, period)) continue;
            const ledgerDay = ledgerDays.get(row.dateKey) || { income: 0, spending: 0, net: 0 };
            const incomeVariance = row.revenue - ledgerDay.income;
            const spendingVariance = row.spending - ledgerDay.spending;
            const netVariance = row.net - ledgerDay.net;
            auditDays.push({
                dateKey: row.dateKey,
                dayStartMs: row.dayStartMs,
                ledgerIncome: ledgerDay.income,
                ledgerSpending: ledgerDay.spending,
                ledgerNet: ledgerDay.net,
                overviewIncome: row.revenue,
                overviewSpending: row.spending,
                overviewNet: row.net,
                incomeVariance,
                spendingVariance,
                netVariance,
                exact: Math.abs(incomeVariance) <= 1 && Math.abs(spendingVariance) <= 1 && Math.abs(netVariance) <= 1
            });
            coveredLedgerIncome += ledgerDay.income;
            coveredLedgerSpending += ledgerDay.spending;
            coveredLedgerNet += ledgerDay.net;
            overviewIncome += row.revenue;
            overviewSpending += row.spending;
            overviewNet += row.net;
            const midpoint = row.dayStartMs + 12 * 60 * 60 * 1000;
            const bucket = base.buckets.find(candidate => midpoint >= candidate.start && midpoint < candidate.end);
            if (bucket) {
                bucket.income += incomeVariance;
                bucket.spending += Math.abs(row.spending) - Math.abs(ledgerDay.spending);
                bucket.net += netVariance;
            }
        }
        if (!auditDays.length) return { ...base, overviewAudit: emptyAudit };
        const incomeVariance = overviewIncome - coveredLedgerIncome;
        const spendingVariance = overviewSpending - coveredLedgerSpending;
        const netVariance = overviewNet - coveredLedgerNet;
        const income = summary.income + incomeVariance;
        const spending = Math.max(0, summary.spending + Math.abs(overviewSpending) - Math.abs(coveredLedgerSpending));
        const net = income - spending;
        const status = Math.abs(netVariance) <= 1 && auditDays.every(day => day.exact)
            ? (overview.coverageReached ? 'reconciled' : 'partial')
            : 'variance';
        const label = status === 'reconciled'
            ? `${auditDays.length.toLocaleString('en-GB')} overview day${auditDays.length === 1 ? '' : 's'} fully reconciled`
            : status === 'partial'
                ? `${auditDays.length.toLocaleString('en-GB')} overview day${auditDays.length === 1 ? '' : 's'} reconciled; requested range exceeds fetched overview coverage`
                : `Overview checkpoint variance ${formatSignedCredits(netVariance)}`;
        const calendarHours = Math.max(1 / 60, Number(summary.calendarHours) || period.durationMs / 3600000);
        const activeHours = Math.max(0.25, Number(summary.activeHours) || 0.25);
        const bucketIncomeValues = base.buckets.map(bucket => bucket.income);
        return {
            ...base,
            income,
            spending,
            net,
            incomePerHour: Math.round(income / calendarHours),
            activeIncomePerHour: Math.round(income / activeHours),
            operatingMarginPercent: income ? Math.round((summary.operatingResult / income) * 1000) / 10 : summary.operatingExpense ? -100 : 0,
            capitalInvestmentRatioPercent: income ? Math.round((summary.capitalInvestment / income) * 1000) / 10 : summary.capitalInvestment ? 100 : 0,
            allianceIncomePercent: income ? Math.round((summary.allianceIncome / income) * 1000) / 10 : 0,
            personalIncomePercent: income ? Math.round((summary.personalIncome / income) * 1000) / 10 : 0,
            incomeConcentrationPercent: income && summary.topIncomeCategory ? Math.round((summary.topIncomeCategory.total / income) * 1000) / 10 : 0,
            incomeVolatilityPercent: bucketIncomeValues.length && income
                ? Math.round((standardDeviation(bucketIncomeValues) / Math.max(1, bucketIncomeValues.reduce((sum, value) => sum + value, 0) / bucketIncomeValues.length)) * 1000) / 10
                : 0,
            overviewAudit: {
                available: true,
                status,
                label,
                rowsUsed: auditDays.length,
                rowsCompared: auditDays.length,
                pageCount: Number(overview.pageCount) || 0,
                lastPage: Number(overview.lastPage) || 0,
                coverageReached: Boolean(overview.coverageReached),
                malformedRowCount: Number(overview.malformedRowCount) || 0,
                duplicateDateCount: Number(overview.duplicateDateCount) || 0,
                ledgerIncome: coveredLedgerIncome,
                ledgerSpending: Math.abs(coveredLedgerSpending),
                ledgerNet: coveredLedgerNet,
                overviewIncome,
                overviewSpending: Math.abs(overviewSpending),
                overviewNet,
                incomeVariance,
                spendingVariance,
                netVariance,
                unresolvedVariance: Math.abs(netVariance) <= 1 ? 0 : netVariance,
                days: auditDays,
                error: String(overview.error || '')
            }
        };
    }

    function percentageChange(current, previous) {
        const currentValue = Number(current) || 0;
        const previousValue = Number(previous) || 0;
        if (!previousValue) return currentValue ? null : 0;
        return ((currentValue - previousValue) / Math.abs(previousValue)) * 100;
    }

    function formatPercentageChange(value) {
        if (value === null || !Number.isFinite(value)) return 'New activity';
        const rounded = Math.round(value * 10) / 10;
        return `${rounded > 0 ? '+' : ''}${rounded.toLocaleString('en-GB')}%`;
    }

    function buildFinancialComparison(current, previous) {
        return {
            incomeChange: percentageChange(current.income, previous.income),
            operatingResultChange: percentageChange(current.operatingResult, previous.operatingResult),
            capitalInvestmentChange: percentageChange(current.capitalInvestment, previous.capitalInvestment),
            spendingChange: percentageChange(current.spending, previous.spending),
            netChange: percentageChange(current.net, previous.net),
            missionChange: current.missionCount - previous.missionCount,
            averageRewardChange: percentageChange(current.averageMissionReward, previous.averageMissionReward),
            activeVelocityChange: percentageChange(current.activeIncomePerHour, previous.activeIncomePerHour),
            currentNet: current.net,
            previousNet: previous.net
        };
    }

    function calculateVaultReconciliation(vault, period, currentTransactions, currentBalance) {
        const checkpoints = Array.isArray(vault?.balanceCheckpoints) ? vault.balanceCheckpoints.slice().sort((a, b) => a.timestamp - b.timestamp) : [];
        let startCheckpoint = null;
        let endCheckpoint = null;
        for (const checkpoint of checkpoints) {
            if (checkpoint.timestamp <= period.startMs) startCheckpoint = checkpoint;
            if (checkpoint.timestamp >= period.endMs && !endCheckpoint) endCheckpoint = checkpoint;
        }
        if (!endCheckpoint && Number.isFinite(Number(currentBalance)) && Math.abs(Date.now() - period.endMs) < 10 * 60 * 1000) {
            endCheckpoint = { timestamp: Date.now(), balance: Math.round(currentBalance) };
        }
        if (!startCheckpoint || !endCheckpoint || endCheckpoint.timestamp <= startCheckpoint.timestamp) {
            return { reconciled: false, difference: null, label: 'Reconstructed from current balance and ledger', startCheckpoint, endCheckpoint };
        }
        const movement = currentTransactions
            .filter(entry => entry.timestamp > startCheckpoint.timestamp && entry.timestamp <= endCheckpoint.timestamp)
            .reduce((sum, entry) => sum + Number(entry.amount || 0), 0);
        const difference = Math.round((endCheckpoint.balance - startCheckpoint.balance) - movement);
        return {
            reconciled: Math.abs(difference) <= 1,
            difference,
            label: Math.abs(difference) <= 1 ? 'Reconciled against saved balance checkpoints' : `Checkpoint variance ${formatSignedCredits(difference)}`,
            startCheckpoint,
            endCheckpoint
        };
    }

    function financialScoreLabel(score) {
        if (score >= 90) return { grade: 'A+', label: 'Exceptional command' };
        if (score >= 82) return { grade: 'A', label: 'Strong command' };
        if (score >= 74) return { grade: 'B+', label: 'Healthy expansion' };
        if (score >= 66) return { grade: 'B', label: 'Stable position' };
        if (score >= 56) return { grade: 'C+', label: 'Mixed position' };
        if (score >= 45) return { grade: 'C', label: 'Watch position' };
        if (score >= 32) return { grade: 'D', label: 'Financial pressure' };
        return { grade: 'F', label: 'Critical pressure' };
    }

    function calculateFinancialScorecard(summary, comparison, { complete = true, balanceAvailable = true, reconciled = false, closingBalance = null } = {}) {
        const incomeTrend = comparison?.incomeChange;
        let revenue = 65;
        if (Number.isFinite(incomeTrend)) revenue += Math.max(-25, Math.min(25, incomeTrend / 2));
        if (summary.activeIncomePerHour > summary.incomePerHour * 1.5) revenue += 4;
        revenue = Math.round(clamp(revenue, 0, 100, 65));
        let efficiency = 55 + summary.operatingMarginPercent * 0.45;
        if (summary.operatingExpense === 0 && summary.income > 0) efficiency += 8;
        efficiency = Math.round(clamp(efficiency, 0, 100, 55));
        const dailyOperatingExpense = summary.operatingExpense / Math.max(1 / 24, Number(summary.calendarDays) || 1 / 24);
        const runwayDays = balanceAvailable && dailyOperatingExpense > 0 ? Math.max(0, Number(closingBalance) || 0) / dailyOperatingExpense : null;
        let liquidity = balanceAvailable ? 65 : 40;
        if (runwayDays !== null) liquidity += Math.max(-30, Math.min(30, (runwayDays - 7) * 2));
        liquidity = Math.round(clamp(liquidity, 0, 100, 60));
        const capexRatio = summary.capitalInvestmentRatioPercent;
        let growth = summary.capitalInvestment > 0 ? 72 : 58;
        if (capexRatio > 200) growth -= 18;
        else if (capexRatio > 120) growth -= 8;
        else if (capexRatio >= 20 && capexRatio <= 100) growth += 10;
        growth = Math.round(clamp(growth, 0, 100, 60));
        let confidence = summary.classificationConfidence;
        if (!complete) confidence -= 18;
        if (!balanceAvailable) confidence -= 8;
        if (reconciled) confidence += 5;
        confidence = Math.round(clamp(confidence, 0, 100, 75));
        const overall = Math.round(revenue * 0.25 + efficiency * 0.25 + liquidity * 0.20 + growth * 0.15 + confidence * 0.15);
        const assessment = financialScoreLabel(overall);
        return {
            overall,
            grade: assessment.grade,
            label: assessment.label,
            revenue,
            efficiency,
            liquidity,
            growth,
            confidence,
            runwayDays: runwayDays === null ? null : Math.round(runwayDays * 10) / 10,
            operatingMarginPercent: summary.operatingMarginPercent
        };
    }

    function calculateFinancialDrawdown(openingBalance, transactions) {
        if (!Number.isFinite(Number(openingBalance))) return { peakBalance: null, lowBalance: null, largestDrawdown: null, largestDrawdownPercent: null };
        let balance = Number(openingBalance);
        let peak = balance;
        let low = balance;
        let largestDrawdown = 0;
        let largestDrawdownPercent = 0;
        for (const entry of transactions.slice().sort((a, b) => a.timestamp - b.timestamp)) {
            balance += Number(entry.amount) || 0;
            peak = Math.max(peak, balance);
            low = Math.min(low, balance);
            const drawdown = Math.max(0, peak - balance);
            if (drawdown > largestDrawdown) {
                largestDrawdown = drawdown;
                largestDrawdownPercent = peak ? drawdown / peak * 100 : 0;
            }
        }
        return { peakBalance: Math.round(peak), lowBalance: Math.round(low), largestDrawdown: Math.round(largestDrawdown), largestDrawdownPercent: Math.round(largestDrawdownPercent * 10) / 10 };
    }

    function buildFinancialRiskAlerts(summary, comparison, context = {}) {
        const alerts = [];
        const add = (severity, title, detail) => alerts.push({ severity, title, detail });
        const risk = activeFinancialPolicy?.risk || BUILTIN_FINANCIAL_POLICY.risk;
        if (!context.ledgerComplete) add('high', 'Partial ledger coverage', 'The requested period was not fully verified from the MissionChief ledger or local archive.');
        if (context.overviewStatus === 'variance') add('high', 'Credits overview variance', `MissionChief daily aggregates differ from the detailed ledger by ${formatSignedCredits(context.overviewVariance)}. Aggregate totals use the overview checkpoint while categories remain ledger-derived.`);
        else if (context.overviewStatus === 'partial') add('medium', 'Partial overview coverage', 'Only the complete daily rows available from MissionChief were reconciled; the remaining period retains detailed-ledger totals.');
        else if (context.overviewStatus === 'unavailable') add('low', 'Credits overview unavailable', 'The report remains operational using the detailed ledger, but daily aggregate verification could not be completed.');
        if (context.archiveTruncated) add('high', 'Local archive capacity reached', `${Number(context.droppedTransactions || 0).toLocaleString('en-GB')} older transactions were not retained locally. Run the report directly against MissionChief for the widest currently accessible range.`);
        if (context.scanLimitReached) add('high', 'Ledger page safety cap reached', 'MissionChief exposed more ledger pages than the configured deep-scan safety cap. The report is extensive but not complete.');
        if (context.scanCancelled) add('medium', 'Deep scan stopped', 'The report uses all pages collected before the scan was stopped. Those pages remain stored in the local archive.');
        if (summary.classificationConfidence < risk.classificationCritical) add('high', 'Low classification confidence', `${summary.unclassifiedCount.toLocaleString('en-GB')} transactions remain uncertain; review the original descriptions.`);
        else if (summary.classificationConfidence < risk.classificationWarning) add('medium', 'Classification review advised', `${summary.classificationConfidence.toLocaleString('en-GB')}% weighted classification confidence.`);
        if (summary.operatingResult < 0) add('high', 'Negative operating result', `Operating activity is ${formatSignedCredits(summary.operatingResult)} before capital investment.`);
        if (summary.capitalInvestmentRatioPercent >= risk.capitalIncomeRatio && summary.capitalInvestment > 0) add('medium', 'Aggressive capital deployment', `Capital investment is ${summary.capitalInvestmentRatioPercent.toLocaleString('en-GB')}% of period income.`);
        if (summary.allianceIncomePercent >= risk.allianceConcentration) add('medium', 'Alliance income concentration', `${summary.allianceIncomePercent.toLocaleString('en-GB')}% of income is alliance-derived.`);
        if (summary.incomeConcentrationPercent >= risk.categoryConcentration) add('medium', 'Revenue concentration', `${summary.incomeConcentrationPercent.toLocaleString('en-GB')}% of income came from ${summary.topIncomeCategory?.label || 'one category'}.`);
        if (summary.incomeVolatilityPercent >= risk.volatilityWarning) add('low', 'High income volatility', `Bucket-to-bucket income volatility is ${summary.incomeVolatilityPercent.toLocaleString('en-GB')}%.`);
        if (comparison && Number.isFinite(comparison.incomeChange) && comparison.incomeChange <= risk.revenueContraction) add('high', 'Revenue contraction', `Income fell ${Math.abs(Math.round(comparison.incomeChange * 10) / 10).toLocaleString('en-GB')}% versus the previous equivalent period.`);
        if (Number.isFinite(context.drawdown?.largestDrawdownPercent) && context.drawdown.largestDrawdownPercent >= risk.drawdownWarning) add('medium', 'Material reserve drawdown', `Largest reconstructed drawdown was ${context.drawdown.largestDrawdownPercent.toLocaleString('en-GB')}%.`);
        if (context.scorecard?.runwayDays !== null && context.scorecard?.runwayDays < risk.runwayCriticalDays) add('high', 'Low operating runway', `Current reserve covers approximately ${context.scorecard.runwayDays.toLocaleString('en-GB')} days at the observed operating-expense pace.`);
        if (!alerts.length) add('good', 'No material alerts', 'No configured financial risk threshold was triggered for this period.');
        return alerts.slice(0, 8);
    }

    function buildFinancialForecast(summary, period, closingBalance) {
        const durationDays = Math.max(1 / 24, period.durationMs / 86400000);
        const dailyIncome = summary.income / durationDays;
        const dailyOperatingResult = summary.operatingResult / durationDays;
        const sevenDayIncome = Math.round(dailyIncome * 7);
        const thirtyDayIncome = Math.round(dailyIncome * 30);
        const recoveryDays = summary.capitalInvestment > 0 && dailyOperatingResult > 0 ? summary.capitalInvestment / dailyOperatingResult : null;
        let endOfDayIncome = null;
        if (period.id === 'today') {
            const elapsedHours = Math.max(0.25, (Date.now() - localDayStart()) / 3600000);
            endOfDayIncome = Math.round(summary.income / elapsedHours * 24);
        }
        const confidence = summary.activityCount >= 100 && durationDays >= 7 ? 'HIGH' : summary.activityCount >= 25 && durationDays >= 1 ? 'MEDIUM' : 'LOW';
        return {
            dailyIncome: Math.round(dailyIncome),
            dailyOperatingResult: Math.round(dailyOperatingResult),
            sevenDayIncome,
            thirtyDayIncome,
            endOfDayIncome,
            recoveryDays: recoveryDays === null ? null : Math.round(recoveryDays * 10) / 10,
            projectedSevenDayBalance: Number.isFinite(Number(closingBalance)) ? Math.round(Number(closingBalance) + dailyOperatingResult * 7) : null,
            confidence
        };
    }


    function currentFinancialReportSignature() {
        return JSON.stringify({
            period: state.discordReport.period,
            customStart: state.discordReport.customStart,
            customEnd: state.discordReport.customEnd,
            includeChart: state.discordReport.includeChart,
            includeComparison: state.discordReport.includeComparison,
            complexity: normaliseDiscordReportComplexity(state.discordReport.complexity),
            includeForecast: state.discordReport.includeForecast,
            includeRisk: state.discordReport.includeRisk,
            topCategories: state.discordReport.topCategories,
            ruleVersion: activeFinancialRuleVersion,
            policyVersion: activeFinancialPolicyVersion,
            sinceLastAnchor: state.discordReport.period === 'sinceLast' ? getLastDiscordReportAt() : 0
        });
    }

