    const targetQueues={'dispatch-recruitment':()=>dispatchRecruitmentPlannedQueue(),'station-icon-copier':()=>stationIconPlannedQueue(),'expansion-and-upgrade-planner':()=>expansionPlannerPlannedQueue(),'alliance-courses':()=>queue.slice(0,ALLIANCE_COURSE_START_LIMIT),'co-admin-patient-transport-sweep':()=>queue};
    data.targets=targetQueues[id]().map(item=>(item.name||item.caption||'Item')+(item.label?' · '+item.label:'')+(Number.isFinite(item.priceCredits)?' · '+item.priceCredits.toLocaleString()+' Credits':''));
